-- Topics
INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'A2.2', 9, 'Polite Forms (Konjunktiv II)', 'Höfliche Bitten und Wünsche: würde, könnte, hätte, wäre', 'konjunktiv-ii-polite', 'Make polite requests, wishes and suggestions with würde, könnte, hätte and wäre — the polite twins of konnte, hatte and war. You need these forms for Goethe A2 Sprechen Teil 3 (making a suggestion and reacting to one) and Schreiben Teil 2 (a polite request in a semi-formal e-mail).', 'Sei höflich: Bitten, Wünsche und Vorschläge mit würde, könnte, hätte, wäre. Das sind die höflichen Formen von konnte, hatte und war. Du brauchst sie im Goethe A2: Sprechen Teil 3 und Schreiben Teil 2.', 22, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['modal-verbs-past','simple-past-sein-haben','modal-verbs-intro']::text[], ARRAY['konjunktiv-ii-wurde','konjunktiv-ii-ware-hatte','future-tense']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid);

INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'A2.2', 10, 'Verbs with Prepositions', 'Verben mit Präpositionen', 'verbs-with-prepositions-intro', 'Learn the fixed preposition and case that go with everyday A2 verbs: warten auf, sich freuen über, sich interessieren für and more, plus the wo(r)-/da(r)- questions and answers for things. Goethe A2 needs these in Sprechen Teil 1–3 and Schreiben Teil 2.', 'Lerne die feste Präposition und den festen Kasus bei wichtigen A2-Verben. Zum Beispiel: warten auf, sich freuen über, sich interessieren für. Das brauchst du im Goethe A2: Sprechen Teil 1–3, Schreiben Teil 2.', 22, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['reflexive-verbs','prepositions-accusative','prepositions-dative']::text[], ARRAY['verbs-with-prepositions','reflexive-verbs','pronouns-accusative-dative','two-way-prepositions']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid);

INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'A2.2', 11, 'Indirect Questions: ob & W-Word', 'Indirekte Fragen mit ob und W-Wort', 'indirect-questions-intro', 'Ask politely without repeating a question word for word: Wissen Sie, ob der Zug pünktlich ist? or Können Sie mir sagen, wo der Bahnhof ist? The verb moves to the end, exactly like in the weil- and dass-clauses you already know. Goethe A2 needs this in Schreiben Teil 2 (asking for information) and Sprechen Teil 1.', 'Frag höflich und wiederhole die Frage nicht direkt: Wissen Sie, ob der Zug pünktlich ist? Das Verb steht am Ende, genau wie bei weil und dass. Du brauchst das im Goethe A2: Schreiben Teil 2, Sprechen Teil 1.', 22, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['subordinating-conjunctions','subordinate-word-order','question-words']::text[], ARRAY['indirect-questions','question-words','subordinating-conjunctions','yes-no-questions']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = '316c318e-cfa2-5a57-b690-891e137d4180'::uuid);

INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'A2.2', 12, 'Infinitive with zu', 'Infinitiv mit zu', 'infinitive-with-zu-intro', 'Say what you feel like doing, forgot to do, or plan to do: Lust haben, vergessen, versuchen, vorhaben and more, each followed by a comma and zu + infinitive. Goethe A2 needs this in Schreiben Teil 1 (SMS invitations and Absagen) and Sprechen Teil 2-3.', 'Lerne den Infinitiv mit zu nach Lust haben, vergessen, versuchen, vorhaben und mehr. Bei einer längeren zu-Gruppe steht ein Komma davor. Du brauchst das im Goethe A2: Schreiben Teil 1 (SMS), Sprechen Teil 2-3.', 23, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['subordinate-word-order','separable-verbs','modal-verbs-intro']::text[], ARRAY['infinitive-with-zu','um-zu-ohne-zu','modal-verbs-intro']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid);

-- Rules
INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'e5ebea77-14f9-5c22-90a3-bbdd85065a17'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'introduction', 'Polite Requests and Wishes: Introduction', 'Einführung: Höfliche Bitten und Wünsche', '{"hook_de":"Könnten Sie mir bitte helfen? Ich hätte eine Frage.","hook_en":"Could you help me, please? I have a question. Four small words make German sound polite: würde, könnte, hätte, wäre.","scenario_en":"Asking for help politely, making a suggestion to a friend, and reacting when someone suggests something.","preview_note_en":"You already know konnte, hatte and war — add an Umlaut and you get könnte, hätte, wäre. würde is the new one.","preview_highlight":"würde, könnte, hätte, wäre","preview_example_de":"Wir könnten am Samstag ins Kino gehen.","preview_example_en":"We could go to the cinema on Saturday.","why_it_matters_en":"Goethe A2 Sprechen Teil 3 asks you to make a suggestion and react to your partner''s suggestion. Schreiben Teil 2 needs a polite request in a semi-formal e-mail.","german_difference_en":"English changes the whole verb (can → could, have → had). German just adds an Umlaut to a form you already know: konnte → könnte, hatte → hätte, war → wäre.","english_comparison_en":"würde has no matching old form to build on — it comes from werden and pairs with an infinitive at the end: Ich würde gern kommen. (I would like to come.)"}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'e5ebea77-14f9-5c22-90a3-bbdd85065a17'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '8e15bdfa-c6aa-5034-bff1-7bea055254d0'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'table', 'The Four Polite Forms', 'Die vier höflichen Formen', '{"type":"case_table","headers":["Person","würde","könnte","hätte","wäre"],"rows":[["ich","würde","könnte","hätte","wäre"],["du","würdest","könntest","hättest","wärst"],["er/sie/es","würde","könnte","hätte","wäre"],["wir","würden","könnten","hätten","wären"],["ihr","würdet","könntet","hättet","wärt"],["sie/Sie","würden","könnten","hätten","wären"]],"highlight_row":-1,"description_de":"ich und er/sie/es sind wieder gleich. Das kennst du von konnte und hatte.","description_en":"ich and er/sie/es share one form again, exactly like konnte and hatte. würde takes the same endings: -st, -, -n, -t, -n."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'You already know three of them: könnte, hätte, wäre. Only würde is brand new.', 'Drei Formen kennst du schon: könnte, hätte, wäre. Nur würde ist ganz neu.', NULL, NULL, 'du wärst drops a syllable people expect: not wärest, just wärst.', 'Bei du heißt es wärst, nicht wärest.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '8e15bdfa-c6aa-5034-bff1-7bea055254d0'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '55c8b7b5-f199-5f31-96b6-379d72ac135e'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'pattern', 'From konnte, hatte, war to könnte, hätte, wäre', 'Von konnte, hatte, war zu könnte, hätte, wäre', '{"type":"steps","steps":[{"step":1,"title_de":"Nimm die Präteritum-Form. Du kennst sie schon.","title_en":"Take the Präteritum form you already know.","detail_de":"konnte, hatte, war — aus Modalverben im Präteritum und aus dem einfachen Präteritum von sein/haben.","detail_en":"konnte, hatte, war — from modal-verbs-past and simple-past-sein-haben."},{"step":2,"title_de":"Setz einen Umlaut.","title_en":"Add an Umlaut.","detail_de":"konnte → könnte, hatte → hätte. Bei war → wäre kommt noch ein e dazu.","detail_en":"konnte → könnte, hatte → hätte. war → wäre also adds an extra -e, so it isn''t just the Umlaut."},{"step":3,"title_de":"würde kommt von werden.","title_en":"würde comes from werden.","detail_de":"werden kennst du aus dem Futur. würde ist die höfliche Form dafür, mit Infinitiv am Ende.","detail_en":"You know werden from future-tense. würde is its polite twin, and it needs an infinitive at the end: Ich würde gern kommen."},{"step":4,"title_de":"Die Endungen bleiben meist gleich.","title_en":"The endings mostly stay the same.","detail_de":"Die Endungen sind meist wie im Präteritum. Bei sein sind du- und ihr-Form kurz: wärst, wärt.","detail_en":"The endings mostly match the Präteritum, but sein stays short in the du- and ihr-forms: wärst, wärt."}],"description_de":"Kein neues System. Nur ein Umlaut auf einer bekannten Form. Dazu ein neues Wort: würde.","description_en":"No new system to learn — just an Umlaut on a form you already have, plus one brand-new word: würde."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'konnte, hatte, war are the everyday past; könnte, hätte, wäre are their polite version. sein alone stays short: wärst, wärt.', 'konnte, hatte, war sind die Vergangenheit. könnte, hätte, wäre sind höflich. Nur sein bleibt kurz: wärst, wärt.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '55c8b7b5-f199-5f31-96b6-379d72ac135e'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'c1f81784-8eae-5310-a597-a2469210c02d'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'table', 'Four Uses: Bitten, Wünsche, Vorschläge, Reaktion', 'Vier Situationen: Bitten, Wünsche, Vorschläge, Reaktion', '{"type":"case_table","headers":["Situation","Form","Beispiel"],"rows":[["Höfliche Bitte","Könnten Sie …? / Würden Sie …?","Könnten Sie mir bitte helfen?"],["Wunsch","hätte gern / würde gern","Ich hätte gern einen Kaffee."],["Vorschlag","könnten / Wie wäre es mit …?","Wir könnten ins Kino gehen."],["Reaktion","wäre + Adjektiv","Das wäre schön."]],"highlight_row":-1,"description_de":"Für eine Bitte an eine fremde Person nimmst du Sie. Für einen Vorschlag unter Freunden nimmst du wir oder du.","description_en":"Use Sie for a polite request to a stranger; use wir or du for a suggestion among friends."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Wie wäre es mit + Dativ is a fixed chunk for suggestions: Wie wäre es mit einem Kaffee?', 'Wie wäre es mit + Dativ ist ein fester Ausdruck: Wie wäre es mit einem Kaffee?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'c1f81784-8eae-5310-a597-a2469210c02d'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '882a0c5e-fc31-589c-af9f-5d464085d733'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'explanation_comparison', 'möchte, hätte gern, würde gern: How They Differ', 'möchte, hätte gern, würde gern im Vergleich', '{"type":"case_table","headers":["Form","Vor einem Nomen","Vor einem Infinitiv","Beispiel"],"rows":[["möchte","ja","ja","Ich möchte einen Kaffee. / Ich möchte kommen."],["hätte gern","ja","nein","Ich hätte gern einen Kaffee."],["würde gern","nein","ja","Ich würde gern kommen."]],"highlight_row":-1,"description_de":"hätte gern steht vor einem Nomen. würde gern steht vor einem Infinitiv am Ende. möchte kann beides.","description_en":"hätte gern pairs with a noun, würde gern pairs with an infinitive at the end — möchte, which you already know, can do either."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'hätte gern plus an infinitive does not exist: say würde gern instead.', 'hätte gern plus Infinitiv gibt es nicht. Sag würde gern.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '882a0c5e-fc31-589c-af9f-5d464085d733'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '94047aa1-24e9-5c73-abe3-ac01bbcc81a6'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'dialogue', 'Dialogue: Planning the Weekend', 'Dialog: das Wochenende planen', '{"speakers":["Mia","Jonas"],"exchanges":[{"speaker":"Mia","text_de":"Was machen wir am Wochenende? Wir könnten ins Kino gehen.","text_en":"What shall we do this weekend? We could go to the cinema.","grammar_note":"könnten — Vorschlag mit wir"},{"speaker":"Jonas","text_de":"Das wäre schön, aber ich wäre lieber draußen.","text_en":"That would be nice, but I''d rather be outdoors.","grammar_note":"wäre — Reaktion und Wunsch (lieber draußen sein)"},{"speaker":"Mia","text_de":"Wie wäre es mit einem Spaziergang im Park?","text_en":"How about a walk in the park?","grammar_note":"Wie wäre es mit + Dativ — ein fester Ausdruck für einen Vorschlag"},{"speaker":"Jonas","text_de":"Gute Idee! Das wäre super. Könntest du auch Getränke mitbringen?","text_en":"Good idea! That would be great. Could you also bring drinks?","grammar_note":"Könntest du — höfliche Bitte, du-Form"},{"speaker":"Mia","text_de":"Ja klar, das mache ich gern. Würdest du die Musik mitbringen?","text_en":"Sure, I''ll gladly do that. Would you bring the music?","grammar_note":"Würdest du — höfliche Bitte mit werden"},{"speaker":"Jonas","text_de":"Ja, ich würde die Musik gern mitbringen. Ich hätte gern deine fröhliche Musik.","text_en":"Yes, I''d love to bring the music. I would like your cheerful music.","grammar_note":"würde gern — Wunsch mit Infinitiv; hätte gern — Wunsch mit Nomen"}],"context_de":"Mia und Jonas planen das Wochenende. Sie sind Freunde und benutzen du.","context_en":"Mia and Jonas are planning the weekend. They are close friends and use du.","grammar_focus_en":"Suggestions with könnten and wir, a reaction with wäre, a fixed suggestion chunk with Wie wäre es mit, and polite requests with Könntest du / Würdest du — this whole exchange mirrors Goethe A2 Sprechen Teil 3."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Sprechen Teil 3 asks exactly this: make a suggestion, then react to your partner''s suggestion.', 'Genau das prüft Sprechen Teil 3: einen Vorschlag machen und dann reagieren.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '94047aa1-24e9-5c73-abe3-ac01bbcc81a6'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'd555098a-2957-55b8-badc-d5f4a6c24889'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'tip', 'Polite Requests in a Semi-Formal E-Mail', 'Höfliche Bitten in der halbformellen E-Mail', '{"content_de":"In einer E-Mail an ein Amt oder eine Firma bist du höflich. Nimm Sie und Konjunktiv II: Könnten Sie mir bitte helfen? Ich hätte noch eine Frage. Würden Sie mir bitte antworten?","content_en":"In an e-mail to an office or a company you stay polite: use Sie with Konjunktiv II. Könnten Sie mir bitte helfen? Ich hätte noch eine Frage. Würden Sie mir bitte antworten? These three lines work as a request, a question and a closing line in a Schreiben Teil 2 e-mail."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'This is exactly what Schreiben Teil 2 tests: at least one polite request or question in a semi-formal e-mail.', 'Genau das prüft Schreiben Teil 2: mindestens eine höfliche Bitte oder Frage in der E-Mail.', 'bitte makes a request even more polite: Könnten Sie mir bitte helfen?', 'bitte macht eine Bitte noch höflicher: Könnten Sie mir bitte helfen?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'd555098a-2957-55b8-badc-d5f4a6c24889'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'bd57dff3-57c0-5671-9741-1bb0845722f4'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'common_mistakes', 'Common Mistakes with the Polite Forms', 'Häufige Fehler bei den höflichen Formen', '{"content_de":"Diese Fehler kommen oft vor. Lies die Beispiele langsam und vergleiche sie.","content_en":"These mistakes come up again and again. Read the pairs slowly and compare them."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich würde gern einen Kaffee.","correct":"Ich hätte gern einen Kaffee.","explanation_de":"würde gern braucht einen Infinitiv am Ende. Vor einem Nomen nimmst du hätte gern.","explanation_en":"würde gern needs an infinitive at the end. Before a noun, use hätte gern instead."},{"wrong":"Könnten Sie helfen mir?","correct":"Könnten Sie mir bitte helfen?","explanation_de":"Das Pronomen mir steht vor dem Infinitiv. Der Infinitiv helfen steht am Ende.","explanation_en":"The pronoun mir comes before the infinitive; helfen closes the sentence at the end."},{"wrong":"Du könntst mir helfen.","correct":"Du könntest mir helfen.","explanation_de":"Bei du kommt noch ein e vor dem -st: könntest, nicht könntst.","explanation_en":"The du-form needs an e before the -st: könntest, not könntst."},{"wrong":"Das würde schön.","correct":"Das wäre schön.","explanation_de":"Eine Reaktion auf einen Vorschlag nimmt wäre, nicht würde ohne Infinitiv.","explanation_en":"A reaction to a suggestion uses wäre, not würde on its own without an infinitive."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'bd57dff3-57c0-5671-9741-1bb0845722f4'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'e91dfa2b-5c40-5f4d-b0f6-1fde92c081db'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["Die vier höflichen Formen: würde, könnte, hätte, wäre.","könnte, hätte = konnte, hatte plus Umlaut. wäre = war plus Umlaut und e.","würde kommt von werden und braucht einen Infinitiv am Ende.","ich und er/sie/es sind gleich; du -st, wir/sie/Sie -n, ihr -t.","Höfliche Bitte: Könnten Sie …? / Würden Sie …?","Wunsch vor einem Nomen: hätte gern. Wunsch vor einem Infinitiv: würde gern.","Vorschlag: Wir könnten … / Wie wäre es mit …?","Reaktion: Das wäre schön. / Das wäre super.","Für Fremde und Ämter: Sie. Für Freunde: du oder wir.","Prüfung: Sprechen Teil 3 (Vorschlag und Reaktion), Schreiben Teil 2 (höfliche Bitte in der E-Mail)."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'e91dfa2b-5c40-5f4d-b0f6-1fde92c081db'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'ba3380aa-2d7c-5f12-ac8b-e99eb55a2e36'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'introduction', 'Verbs with Prepositions: Introduction', 'Einführung: Verben mit Präpositionen', '{"hook_de":"Ich warte auf den Bus. Ich freue mich auf den Urlaub.","hook_en":"I''m waiting for the bus. I''m looking forward to the holiday. Some German verbs always come with one fixed preposition.","scenario_en":"Talking about your interests, plans and worries, or making a phone call — Sprechen Teil 1–3 and Schreiben Teil 2.","preview_note_en":"Each verb has its own preposition and its own case — you learn them together, as one pair.","preview_highlight":"warten auf, sich freuen über, sich interessieren für","preview_example_de":"Ich interessiere mich für Musik.","preview_example_en":"I am interested in music.","why_it_matters_en":"Goethe A2 Sprechen Teil 1 asks about your interests and hobbies, and Schreiben Teil 2 often needs sich freuen auf/über in a personal email.","german_difference_en":"German and English rarely pick the same preposition: warten auf = wait for, denken an = think of. German always keeps one fixed preposition per verb.","english_comparison_en":"German says sich interessieren für where English says interested in — the preposition never translates word for word, so learn verb + preposition + case as one unit."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'ba3380aa-2d7c-5f12-ac8b-e99eb55a2e36'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '2ba2d887-9814-509b-86ed-3ea88ef8b409'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'table', 'The Verbs and Their Fixed Prepositions', 'Die Verben und ihre feste Präposition', '{"type":"case_table","headers":["Verb","Präposition","Kasus","Beispiel"],"rows":[["warten","auf","Akkusativ","Ich warte auf den Bus."],["sich freuen","auf","Akkusativ","Wir freuen uns auf die Ferien."],["sich freuen","über","Akkusativ","Er freut sich über das Geschenk."],["sich interessieren","für","Akkusativ","Ich interessiere mich für Sport."],["denken","an","Akkusativ","Sie denkt an ihre Reise."],["sprechen","über","Akkusativ","Wir sprechen über das Wetter."],["sprechen","mit","Dativ","Ich spreche mit meinem Freund."],["sich ärgern","über","Akkusativ","Er ärgert sich über den Lärm."],["träumen","von","Dativ","Sie träumt von einer Reise."],["sich erinnern","an","Akkusativ","Ich erinnere mich an den Urlaub."],["sich kümmern","um","Akkusativ","Sie kümmert sich um die Kinder."],["anfangen","mit","Dativ","Wir fangen mit der Arbeit an."],["sich bedanken","für","Akkusativ","Ich bedanke mich für die Hilfe."],["fragen","nach","Dativ","Er fragt nach dem Weg."],["Angst haben","vor","Dativ","Ich habe Angst vor Prüfungen."],["telefonieren","mit","Dativ","Ich telefoniere mit meiner Mutter."],["sich anmelden","für","Akkusativ","Ich melde mich für den Kurs an."]],"highlight_row":-1,"description_de":"Jedes Verb hat eine feste Präposition und einen festen Kasus. Lerne sie zusammen, wie ein Paar. Auch möglich: sich zu einem Kurs anmelden (+ Dativ).","description_en":"Every verb has one fixed preposition and one fixed case — learn them together, like a pair, not separately. You may also meet sich zu einem Kurs anmelden (+ Dativ) in a reading or listening text."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '2ba2d887-9814-509b-86ed-3ea88ef8b409'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '4a0f9fea-3288-519f-9f8d-1e72cc762389'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'pattern', 'Asking and Answering About Things: wo(r)- and da(r)-', 'Fragen und Antworten für Sachen: wo(r)- und da(r)-', '{"type":"steps","steps":[{"step":1,"title_de":"Nimm die feste Präposition vom Verb.","title_en":"Start from the verb''s fixed preposition.","detail_de":"warten auf, denken an, sich interessieren für — die Präposition bleibt gleich.","detail_en":"warten auf, denken an, sich interessieren für — the preposition never changes."},{"step":2,"title_de":"Vor einem Vokal kommt ein r dazu: wo + r + Präposition.","title_en":"Before a vowel, add an r: wo + r + preposition.","detail_de":"auf → worauf, an → woran, über → worüber, um → worum.","detail_en":"auf → worauf, an → woran, über → worüber, um → worum — the r keeps the two vowels apart."},{"step":3,"title_de":"Vor einem Konsonanten bleibt es einfach wo-.","title_en":"Before a consonant, wo- stays simple.","detail_de":"für → wofür, mit → womit, von → wovon, nach → wonach.","detail_en":"für → wofür, mit → womit, von → wovon, nach → wonach — no r is needed."},{"step":4,"title_de":"Für die Antwort nimmst du da(r)- nach demselben Muster.","title_en":"For the answer, use da(r)- the same way.","detail_de":"Worauf wartest du? — Ich warte darauf. Woran denkst du? — Ich denke daran.","detail_en":"Worauf wartest du? — Ich warte darauf. Woran denkst du? — Ich denke daran. Same r-rule as wo(r)-."}],"description_de":"wo(r)- fragt nach einer Sache, da(r)- ersetzt sie in der Antwort. Nie bei Personen!","description_en":"wo(r)- asks about a thing; da(r)- replaces it in the answer. Never use these forms for people."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '4a0f9fea-3288-519f-9f8d-1e72cc762389'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '5d9814f4-1d40-547e-82a2-e6124dec7376'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'explanation_comparison', 'Things or People? Two Ways to Ask and Answer', 'Sachen oder Personen? Zwei Arten zu fragen', '{"type":"case_table","headers":["Verb + Präposition","Sache: Frage mit wo(r)-","Person: Frage mit Präposition + wen/wem"],"rows":[["warten auf + Akk","Worauf wartest du?","Auf wen wartest du?"],["denken an + Akk","Woran denkst du?","An wen denkst du?"],["sich kümmern um + Akk","Worum kümmerst du dich?","Um wen kümmerst du dich?"],["träumen von + Dat","Wovon träumst du?","Von wem träumst du?"]],"highlight_row":-1,"description_de":"Bei Sachen: wo(r)- in der Frage, da(r)- in der Antwort. Bei Personen: Präposition + wen/wem in der Frage.","description_en":"For things: wo(r)- in the question, da(r)- in the answer. For people: keep the preposition and add wen/wem in the question, and a pronoun in the answer."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'For people, the answer also keeps the preposition: Ich warte auf ihn. Ich denke an sie.', 'Bei Personen bleibt die Präposition auch in der Antwort: Ich warte auf ihn. Ich denke an sie.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '5d9814f4-1d40-547e-82a2-e6124dec7376'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'ca83c920-0f9f-5eb3-a1b1-2e03052c42ed'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'tip', 'Reflexive Verbs Already Have a Preposition', 'Reflexive Verben haben oft schon eine Präposition', '{"content_de":"Du kennst reflexive Verben aus sich waschen und sich freuen. Viele reflexive Verben haben auch eine feste Präposition. Zum Beispiel: sich freuen auf, sich interessieren für, sich ärgern über. Auch: sich erinnern an, sich kümmern um, sich bedanken für, sich anmelden für. Das Reflexivpronomen steht direkt nach dem Verb, die Präposition kommt später im Satz.","content_en":"You know reflexive verbs from sich waschen and sich freuen. Many reflexive verbs also carry a fixed preposition: sich freuen auf/über, sich interessieren für, sich ärgern über, sich erinnern an, sich kümmern um, sich bedanken für, sich anmelden für. The reflexive pronoun still follows the verb directly; the preposition comes later in the sentence."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'In a formal email (Schreiben Teil 2), ''Ich bedanke mich für Ihre Hilfe.'' is a standard closing line of thanks.', 'In einer E-Mail schreibst du: ''Ich bedanke mich für Ihre Hilfe.''', 'sich freuen auf = something still ahead; sich freuen über = something already here.', 'sich freuen auf = noch in der Zukunft; sich freuen über = schon da.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'ca83c920-0f9f-5eb3-a1b1-2e03052c42ed'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'c554f359-9539-5239-b2de-7d8564e14bfe'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'explanation_patterns', 'Fixed Verbs Keep Their Case — Not wo?/wohin?', 'Feste Verben behalten ihren Kasus — nicht wo/wohin', '{"type":"case_table","headers":["Typ","Beispiel","Erklärung"],"rows":[["Wechselpräposition (bekannt)","Ich stelle das Buch auf den Tisch.","wohin? → Akkusativ (Bewegung)"],["Wechselpräposition (bekannt)","Das Buch liegt auf dem Tisch.","wo? → Dativ (Position)"],["Festes Verb + Präposition (neu)","Ich warte auf den Bus.","warten auf ist immer Akkusativ, unabhängig von wo/wohin"],["Festes Verb + Präposition (neu)","Ich denke an meine Reise.","denken an ist immer Akkusativ, es gibt keine Bewegung"]],"highlight_row":-1,"description_de":"Bei warten auf, denken an und sich freuen auf/über fragst du nicht wo? oder wohin? Das Verb bestimmt den Kasus, nicht die Bewegung.","description_en":"With warten auf, denken an and sich freuen auf/über, don''t ask wo? or wohin? — the verb fixes the case, not movement."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'You already know auf, an, über as Wechselpräpositionen from two-way-prepositions. With a fixed verb, that wo?/wohin? test does not apply — just learn the verb''s own case.', 'Du kennst auf, an, über schon als Wechselpräpositionen. Bei einem festen Verb zählt der wo?/wohin?-Test nicht — lerne den Kasus mit dem Verb.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'c554f359-9539-5239-b2de-7d8564e14bfe'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'de7be9fa-96f7-5b5b-9b1d-ad50d749e52e'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'dialogue', 'Dialogue: Waiting for Exam Results', 'Dialog: Warten auf die Prüfungsergebnisse', '{"speakers":["Anna","Markus"],"exchanges":[{"speaker":"Markus","text_de":"Worauf wartest du so nervös?","text_en":"What are you waiting for so nervously?","grammar_note":"Worauf — wo(r)-Frage für eine Sache"},{"speaker":"Anna","text_de":"Ich warte auf die Prüfungsergebnisse. Ich habe Angst davor.","text_en":"I''m waiting for the exam results. I''m afraid of it.","grammar_note":"warten auf + Akk; Angst haben vor + da(r)-Form (davor)"},{"speaker":"Markus","text_de":"Das verstehe ich. Aber du interessierst dich doch für Medizin, oder?","text_en":"I understand. But you''re interested in medicine, aren''t you?","grammar_note":"sich interessieren für + Akk"},{"speaker":"Anna","text_de":"Ja, genau. Ich freue mich schon auf die Arbeit im Krankenhaus.","text_en":"Yes, exactly. I''m already looking forward to working in the hospital.","grammar_note":"sich freuen auf + Akk, noch Zukunft"},{"speaker":"Markus","text_de":"Kannst du dich noch an deinen ersten Kurstag erinnern?","text_en":"Can you still remember your first day of class?","grammar_note":"sich erinnern an + Akk, Modalverb + Infinitiv am Ende"},{"speaker":"Anna","text_de":"Ja klar! Ich musste mich für den Kurs anmelden.","text_en":"Yes, of course! I had to register for the course.","grammar_note":"sich anmelden für + Akk, trennbares Verb"},{"speaker":"Markus","text_de":"Ruf mich nach der Prüfung an. Ich warte auf deinen Anruf!","text_en":"Call me after the exam. I''m waiting for your call!","grammar_note":"warten auf + Akk, hier eine andere Sache"},{"speaker":"Anna","text_de":"Mach ich! Ich telefoniere sofort mit dir.","text_en":"Will do! I''ll call you right away.","grammar_note":"telefonieren mit + Dativ"}],"context_de":"Anna wartet nervös auf ihre Prüfungsergebnisse. Markus ist ihr Freund.","context_en":"Anna is nervously waiting for her exam results. Markus is her friend.","grammar_focus_en":"Every fixed verb here (warten auf, sich interessieren für, sich freuen auf, sich erinnern an, sich anmelden für, telefonieren mit) keeps its own preposition and case — exactly the everyday talk Sprechen Teil 1–3 asks for."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Sprechen Teil 1 asks exactly this: your interests, your plans, what you are looking forward to.', 'Genau das fragt Sprechen Teil 1: deine Interessen, deine Pläne, worauf du dich freust.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'de7be9fa-96f7-5b5b-9b1d-ad50d749e52e'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'fe31826b-a1c9-5ea1-836e-d1c7b0f0a15e'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'common_mistakes', 'Common Mistakes with Verbs and Prepositions', 'Häufige Fehler bei Verben mit Präpositionen', '{"content_de":"Diese Fehler kommen oft vor. Lies die Beispiele langsam und vergleiche sie.","content_en":"These mistakes come up again and again. Read the pairs slowly and compare them."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich warte für den Bus.","correct":"Ich warte auf den Bus.","explanation_de":"warten braucht immer auf, nicht für.","explanation_en":"warten always takes auf, never für — even though English says ''wait for''."},{"wrong":"Ich interessiere mich an Musik.","correct":"Ich interessiere mich für Musik.","explanation_de":"sich interessieren braucht für, nicht an.","explanation_en":"sich interessieren takes für, not an."},{"wrong":"Ich denke über meine Familie.","correct":"Ich denke an meine Familie.","explanation_de":"denken braucht an, nicht über.","explanation_en":"denken takes an, not über."},{"wrong":"Freut sich er über das Geschenk?","correct":"Freut er sich über das Geschenk?","explanation_de":"In der Frage steht das Reflexivpronomen nach dem Subjekt, nicht davor.","explanation_en":"In a question, the reflexive pronoun follows the subject, not before it."},{"wrong":"Woran denkst du, an deinen Bruder?","correct":"An wen denkst du, an deinen Bruder?","explanation_de":"Bei einer Person fragst du mit an wen, nicht mit woran.","explanation_en":"For a person, ask with an wen, not woran."},{"wrong":"Ich habe Angst von der Prüfung.","correct":"Ich habe Angst vor der Prüfung.","explanation_de":"Angst haben braucht vor, nicht von.","explanation_en":"Angst haben takes vor, not von — a close-sounding mix-up."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'fe31826b-a1c9-5ea1-836e-d1c7b0f0a15e'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '35b84626-1003-5cd5-9a32-139e59e61af2'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["Jedes Verb hat eine feste Präposition und einen festen Kasus.","Beispiel: warten auf + Akk, sprechen mit + Dat.","Der Kasus hängt vom Verb ab, nicht von wo? oder wohin?","Sachen: Frage mit wo(r)- (Worauf?), Antwort mit da(r)- (Darauf).","Personen: Frage mit Präposition + wen/wem, Antwort mit Präposition + Pronomen.","Reflexive Verben haben oft eine Präposition dabei: sich freuen auf/über, sich interessieren für.","sich freuen auf = noch in der Zukunft. sich freuen über = schon passiert.","Vor einem Vokal: wo + r (worauf, woran). Vor einem Konsonanten: wo ohne r (wofür, womit).","Wichtige Verben: warten auf, sich interessieren für, denken an, sich kümmern um.","Auch wichtig: sich bedanken für, Angst haben vor, telefonieren mit.","sich anmelden für ist trennbar: Ich melde mich für den Kurs an.","Prüfung: Sprechen Teil 1–3 (Interessen, Pläne), Schreiben Teil 2 (E-Mail mit sich freuen auf/über)."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '35b84626-1003-5cd5-9a32-139e59e61af2'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '5fcd6289-c1ba-5aeb-975b-c3d858ef83d3'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'introduction', 'Indirect Questions with ob and W-Words: Introduction', 'Einführung: Indirekte Fragen mit ob und W-Wort', '{"hook_de":"Wissen Sie, wo der Bahnhof ist? Das klingt höflicher als: Wo ist der Bahnhof?","hook_en":"Wissen Sie, wo der Bahnhof ist? sounds more polite than the bare question Wo ist der Bahnhof? German builds this with one extra step: the verb moves to the end.","scenario_en":"Asking politely at an office, a train station or a doctor''s practice; writing a polite request in an email.","preview_note_en":"The connector changes (ob or the W-word), but the verb always moves to the end — no exceptions.","preview_highlight":"ob, wo, wann, wie, was, wer, warum, wie viel, wie lange, welch-","preview_example_de":"Ich möchte wissen, ob der Kurs heute stattfindet.","preview_example_en":"I would like to know whether the course is taking place today.","why_it_matters_en":"Goethe A2 Schreiben Teil 2 asks for information in a half-formal email, and Sprechen Teil 1 often opens with a polite question at an Amt, Bahnhof or beim Arzt — both reward exactly this pattern.","german_difference_en":"English keeps normal word order after ''whether'' or a W-word (I know where he lives); German sends the verb all the way to the end (Ich weiß, wo er wohnt).","english_comparison_en":"English: Do you know if the train is on time? German turns ''if'' into ob and pushes the verb to the end: Wissen Sie, ob der Zug pünktlich ist?"}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '5fcd6289-c1ba-5aeb-975b-c3d858ef83d3'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '496bcc13-c5c9-524c-aed0-aa1b31acfbcb'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'table', 'From Direct Question to Indirect Question', 'Von der direkten zur indirekten Frage', '{"type":"case_table","headers":["Direkte Frage","Indirekte Frage","English"],"rows":[["Hat die Bank heute geöffnet?","..., ob die Bank heute geöffnet hat.","Is the bank open today? → ... whether the bank is open today."],["Wo ist der Automat?","..., wo der Automat ist.","Where is the machine? → ... where the machine is."],["Wann kommt der Bus?","..., wann der Bus kommt.","When does the bus come? → ... when the bus comes."],["Wie viel kostet das?","..., wie viel das kostet.","How much does it cost? → ... how much it costs."],["Wer ist heute im Büro?","..., wer heute im Büro ist.","Who is in the office today? → ... who is in the office today."]],"highlight_row":-1,"description_de":"Bei Ja/Nein-Fragen wird ob das neue erste Wort. Bei W-Fragen bleibt das W-Wort. In beiden Fällen wandert das Verb ans Ende.","description_en":"A yes/no question becomes ob + verb-final. A W-question keeps its W-word and simply sends the verb to the end."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'No question word in the original? Then ob is the connector.', 'Keine W-Frage? Dann nimm ob.', NULL, NULL, 'ob works like dass and wenn: it just sends the verb to the end of its clause.', 'ob funktioniert wie dass und wenn: Es schickt das Verb ans Ende.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '496bcc13-c5c9-524c-aed0-aa1b31acfbcb'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '960066a4-dce8-5dc7-ada0-2892cc822ead'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'pattern', 'How to Build an Indirect Question', 'So baust du eine indirekte Frage', '{"type":"steps","steps":[{"step":1,"title_de":"Finde die Originalfrage.","title_en":"Find the original question.","detail_de":"Hat die Bank heute geöffnet? → Ja/Nein-Frage. Wo ist der Automat? → W-Frage.","detail_en":"Hat die Bank heute geöffnet? is a yes/no question; Wo ist der Automat? is a W-question."},{"step":2,"title_de":"Wähle den Konnektor.","title_en":"Choose the connector.","detail_de":"Ja/Nein-Frage → ob. W-Frage → das W-Wort bleibt.","detail_en":"A yes/no question takes ob; a W-question simply keeps its W-word."},{"step":3,"title_de":"Schick das Verb ans Ende.","title_en":"Send the verb to the end.","detail_de":"Hat die Bank heute geöffnet? → ob die Bank heute geöffnet hat. Das Verb steht ganz hinten.","detail_en":"Hat die Bank heute geöffnet? → ob die Bank heute geöffnet hat. The verb goes all the way to the end."},{"step":4,"title_de":"Wähle den Rahmen und die Interpunktion.","title_en":"Choose the frame and the punctuation.","detail_de":"Ein Frage-Rahmen (Wissen Sie …?) bekommt ein Fragezeichen. Ein Aussage-Rahmen (Ich weiß nicht …) bekommt einen Punkt.","detail_en":"A question frame (Wissen Sie …?) keeps a question mark. A statement frame (Ich weiß nicht …) ends in a period."}],"description_de":"Vier Schritte, immer in der gleichen Reihenfolge.","description_en":"Four steps, always in the same order: question type, connector, verb-final, then frame and punctuation."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'The frame decides the punctuation, not the question inside it.', 'Der Rahmen entscheidet über die Interpunktion, nicht die Frage darin.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '960066a4-dce8-5dc7-ada0-2892cc822ead'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '3fa4e369-0fba-5028-a8a1-bb09035a4385'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'table', 'Frames and the Question Mark Rule', 'Rahmen und die Regel zum Fragezeichen', '{"type":"case_table","headers":["Rahmen","Fragezeichen?","Beispiel"],"rows":[["Wissen Sie, …?","ja — der Rahmen ist eine Frage","Wissen Sie, wo der Bahnhof ist?"],["Weißt du, …?","ja","Weißt du, wann der Bus kommt?"],["Kannst du mir sagen, …?","ja","Kannst du mir sagen, wie ich zum Amt komme?"],["Können Sie mir sagen, …?","ja","Können Sie mir sagen, wie viel das kostet?"],["Ich möchte wissen, …","nein — der Rahmen ist eine Aussage","Ich möchte wissen, ob der Kurs stattfindet."],["Ich weiß nicht, …","nein","Ich weiß nicht, wo mein Schlüssel ist."],["Ich habe keine Ahnung, …","nein","Ich habe keine Ahnung, wann der Kurs beginnt."],["Ich frage mich, …","nein","Ich frage mich, warum der Bus so spät kommt."]],"highlight_row":-1,"description_de":"Das Fragezeichen richtet sich nach dem Rahmen, nicht nach der inneren Frage.","description_en":"The question mark depends only on the frame: a question frame keeps it, a statement frame ends in a period."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'The indirect question itself is no longer a question — it''s a clause. Only the frame can make the whole sentence a question.', 'Die indirekte Frage ist selbst keine Frage mehr, sondern ein Nebensatz. Nur der Rahmen entscheidet.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '3fa4e369-0fba-5028-a8a1-bb09035a4385'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '6444732f-4a21-5d68-9878-78f3bb446fc2'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'tip', 'Verb-Final: What You Already Know', 'Verbendstellung: Das kennst du schon', '{"content_de":"Du kennst die Verbendstellung schon aus weil, dass und wenn. ob funktioniert genauso: Ich weiß nicht, ob er kommt. Neu ist nur das W-Wort am Anfang. Beispiel: Ich weiß nicht, wann er kommt.","content_en":"You already know verb-final order from weil, dass and wenn. ob behaves exactly the same way: Ich weiß nicht, ob er kommt. What''s new is just the W-word at the front. Example: Ich weiß nicht, wann er kommt."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'With a modal verb the infinitive comes first and the modal stands last, exactly as in a weil-clause: ..., ob ich das Formular abgeben muss.', 'Mit einem Modalverb steht der Infinitiv zuerst. Das Modalverb steht ganz am Ende: ..., ob ich das Formular abgeben muss.', 'If you can already build a weil-clause, you can already build an indirect question — only the first word changes.', 'Wenn du schon einen weil-Satz bauen kannst, kannst du auch eine indirekte Frage bauen. Nur das erste Wort ist neu.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '6444732f-4a21-5d68-9878-78f3bb446fc2'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '55355446-49b7-55aa-9b49-43d02855ac08'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'explanation_comparison', 'The W-Words in Indirect Questions', 'Die W-Wörter in indirekten Fragen', '{"type":"case_table","headers":["W-Wort","Beispiel","English"],"rows":[["wo","Ich weiß nicht, wo der Bahnhof ist.","I don''t know where the station is."],["wann","Weißt du, wann der Kurs beginnt?","Do you know when the course starts?"],["wie","Kannst du mir sagen, wie ich zum Amt komme?","Can you tell me how to get to the office?"],["was","Ich möchte wissen, was das kostet.","I would like to know what that costs."],["wer","Ich habe keine Ahnung, wer heute im Büro ist.","I have no idea who is in the office today."],["warum","Ich frage mich, warum der Bus nicht kommt.","I wonder why the bus isn''t coming."],["wie viel","Können Sie mir sagen, wie viel das Ticket kostet?","Can you tell me how much the ticket costs?"],["wie lange","Ich weiß nicht, wie lange die Prüfung dauert.","I don''t know how long the exam lasts."],["welch-","Wissen Sie, welches Formular ich brauche?","Do you know which form I need?"],["mit wem","Ich weiß nicht, mit wem ich sprechen soll.","I don''t know who I should talk to."]],"highlight_row":-1,"description_de":"Jedes W-Wort bleibt gleich, nur das Verb wandert ans Ende. Bei einer Person nach einer festen Präposition sagst du: mit wem oder für wen.","description_en":"Every W-word stays the same word; only the verb moves. With a person and a fixed preposition you say mit wem, für wen or um wie viel Uhr instead of a wo(r)-compound."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'wo(r)-compounds like worauf or worüber belong to a different topic (verbs with prepositions) — here you only combine a preposition with wem or wen for people.', 'wo(r)-Wörter wie worauf gehören zu einem anderen Thema. Hier kombinierst du eine Präposition nur mit wem oder wen.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '55355446-49b7-55aa-9b49-43d02855ac08'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '63820b1c-a553-5f4e-a41e-aa530766bf07'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'dialogue', 'Dialogue: At the Citizens'' Office', 'Dialog: im Bürgeramt', '{"speakers":["Frau Toprak","Herr Weber"],"exchanges":[{"speaker":"Frau Toprak","text_de":"Entschuldigung, wissen Sie, wo ich einen neuen Ausweis bekomme?","text_en":"Excuse me, do you know where I can get a new ID card?","grammar_note":"wo + Verb am Ende: bekomme steht am Ende"},{"speaker":"Herr Weber","text_de":"Ja, das ist Zimmer zwölf. Wissen Sie schon, welche Papiere Sie brauchen?","text_en":"Yes, that''s room twelve. Do you already know which papers you need?","grammar_note":"welche + Nomen, Verb am Ende: brauchen"},{"speaker":"Frau Toprak","text_de":"Nein, können Sie mir sagen, was ich mitbringen muss?","text_en":"No, can you tell me what I need to bring?","grammar_note":"was + Modalverb am Ende: mitbringen muss"},{"speaker":"Herr Weber","text_de":"Sie brauchen Ihren alten Ausweis und ein Foto. Wissen Sie, wie viel das kostet?","text_en":"You need your old ID and a photo. Do you know how much it costs?","grammar_note":"wie viel + Verb: kostet"},{"speaker":"Frau Toprak","text_de":"Ich habe keine Ahnung, wie lange das dauert.","text_en":"I have no idea how long it takes.","grammar_note":"Aussage-Rahmen: kein Fragezeichen, Verb am Ende: dauert"},{"speaker":"Herr Weber","text_de":"Meistens zwei Wochen.","text_en":"Usually two weeks.","grammar_note":"kein Nebensatz hier — kurze Antwort zum Vergleich"},{"speaker":"Frau Toprak","text_de":"Ich frage mich, ob ich einen Termin brauche.","text_en":"I wonder whether I need an appointment.","grammar_note":"ob + Verb am Ende: brauche"},{"speaker":"Herr Weber","text_de":"Ja, Sie brauchen einen Termin.","text_en":"Yes, you need an appointment.","grammar_note":"kein Nebensatz hier — normaler Hauptsatz zum Vergleich"}],"context_de":"Frau Toprak fragt im Bürgeramt nach einem neuen Ausweis.","context_en":"Frau Toprak asks about a new ID card at the citizens'' office.","grammar_focus_en":"Every question here uses a polite frame (Wissen Sie / Können Sie mir sagen / Ich frage mich) with the real question turned into a verb-final clause — exactly what Sprechen Teil 1 and a Bürgeramt visit require."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Sprechen Teil 1 often opens with exactly this kind of polite question at an office or station.', 'So beginnt oft Sprechen Teil 1: eine höfliche Frage im Amt oder am Bahnhof.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '63820b1c-a553-5f4e-a41e-aa530766bf07'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'b4b9afa5-49b0-5a31-871c-b47ffa32611d'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'common_mistakes', 'Six Mistakes to Avoid', 'Sechs Fehler im Überblick', '{"content_de":"Diese Fehler kommen oft vor. Lies die Beispiele langsam.","content_en":"These come up again and again. Read the pairs slowly and compare them."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Wissen Sie, wo ist der Bahnhof?","correct":"Wissen Sie, wo der Bahnhof ist?","explanation_de":"Nach dem W-Wort steht das Verb nicht auf Position 2, sondern ganz am Ende.","explanation_en":"After the W-word the verb does not stay in position 2 — it moves all the way to the end."},{"wrong":"Ich weiß nicht wann der Bus kommt.","correct":"Ich weiß nicht, wann der Bus kommt.","explanation_de":"Vor jeder indirekten Frage steht ein Komma, genau wie vor jedem Nebensatz.","explanation_en":"A comma always comes before an indirect question, exactly as before any other Nebensatz."},{"wrong":"Ich möchte wissen, ob der Kurs stattfindet?","correct":"Ich möchte wissen, ob der Kurs stattfindet.","explanation_de":"Ich möchte wissen ist ein Aussage-Rahmen. Der Satz endet mit einem Punkt, nicht mit einem Fragezeichen.","explanation_en":"Ich möchte wissen is a statement frame, so the sentence ends in a period, not a question mark."},{"wrong":"Weißt du, wer arbeitet heute?","correct":"Weißt du, wer heute arbeitet?","explanation_de":"heute gehört auch in die Satzklammer und steht vor dem Verb, nicht danach.","explanation_en":"heute also belongs inside the bracket and stands before the final verb, not after it."},{"wrong":"Ich weiß nicht, ob dass er kommt.","correct":"Ich weiß nicht, ob er kommt.","explanation_de":"Nur ein Konnektor pro Satz. ob und dass stehen nie zusammen.","explanation_en":"Only one connector per clause. ob and dass never appear together."},{"wrong":"Kannst du mir sagen, wieviel kostet das?","correct":"Kannst du mir sagen, wie viel das kostet?","explanation_de":"wie viel schreibt man getrennt, und das Verb kostet wandert ans Ende.","explanation_en":"wie viel is two words, and the verb kostet still moves to the end."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'b4b9afa5-49b0-5a31-871c-b47ffa32611d'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '8a362e3e-7c6d-5373-96e4-7456091e9cfc'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["Ja/Nein-Frage → ob: Ist sie da? → ..., ob sie da ist.","W-Frage → das W-Wort bleibt: Wo ist sie? → ..., wo sie ist.","Das Verb steht immer am Ende: wie bei weil, dass und wenn.","Bei einem Modalverb: Infinitiv zuerst, Modalverb ganz am Ende.","Frage-Rahmen: Wissen Sie, Weißt du, Können Sie mir sagen, Kannst du mir sagen.","Nach einem Frage-Rahmen steht ein Fragezeichen.","Aussage-Rahmen: Ich möchte wissen, Ich weiß nicht, Ich frage mich.","Nach einem Aussage-Rahmen steht ein Punkt.","Immer ein Komma vor der indirekten Frage.","Bei Personen: mit wem, für wen, um wie viel Uhr — keine wo(r)-Wörter.","ob und dass stehen nie zusammen im selben Satz.","Prüfung: Schreiben Teil 2 (E-Mail), Sprechen Teil 1."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '8a362e3e-7c6d-5373-96e4-7456091e9cfc'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '87d845f3-b82c-5973-92b8-7dd9f221e625'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'introduction', 'Infinitive with zu: Introduction', 'Einführung: Infinitiv mit zu', '{"hook_de":"Hast du Lust, heute Abend ins Kino zu gehen?","hook_en":"Do you feel like going to the cinema tonight? German adds a comma, then zu, before the second verb.","scenario_en":"Inviting a friend, cancelling a plan, saying what you forgot, feel like doing, or are planning.","preview_note_en":"One little word, zu, and a comma in front of it — and you can talk about plans, wishes and excuses.","preview_highlight":"Komma + zu + Infinitiv","preview_example_de":"Ich habe keine Zeit, heute einzukaufen.","preview_example_en":"I have no time to go shopping today.","why_it_matters_en":"Goethe A2 Schreiben Teil 1 often asks for an SMS invitation or a short excuse; Sprechen Teil 2-3 asks about plans and wishes — both lean on zu + Infinitiv constantly.","german_difference_en":"English uses ''to'' the same way (I forgot to call), but German also tucks zu inside separable verbs: anzurufen, not zu anrufen.","english_comparison_en":"I try to learn German. -> Ich versuche, Deutsch zu lernen. The comma before the zu-group has no English equivalent."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '87d845f3-b82c-5973-92b8-7dd9f221e625'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'd35600a6-b14d-5ef4-95be-bcc1b7ffe672'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'table', 'Verbs and Expressions Before zu + Infinitive', 'Ausdrücke vor dem Infinitiv mit zu', '{"type":"case_table","headers":["Ausdruck","Beispiel","Englisch"],"rows":[["Lust haben","Ich habe Lust, Pizza zu essen.","I feel like eating pizza."],["(keine) Zeit haben","Ich habe keine Zeit, lange zu telefonieren.","I have no time to talk on the phone for long."],["vergessen","Er hat vergessen, das Fenster zu schließen.","He forgot to close the window."],["versuchen","Wir versuchen, pünktlich zu sein.","We try to be on time."],["anfangen","Sie fängt an, Englisch zu lernen.","She is starting to learn English."],["aufhören","Ich höre auf, so viel zu arbeiten.","I''m going to stop working so much."],["vorhaben","Wir haben vor, im Sommer zu heiraten.","We plan to get married in the summer."],["(keine) Angst haben","Er hat Angst, allein zu fliegen.","He''s afraid to fly alone."],["es ist wichtig / schön / schwer / leicht / möglich","Es ist möglich, hier zu parken.","It''s possible to park here."],["ich finde es …","Ich finde es schön, Freunde zu treffen.","I find it nice to meet friends."],["verboten sein","Es ist verboten, hier zu rauchen.","It''s forbidden to smoke here."],["erlaubt sein","Es ist erlaubt, im Park zu grillen.","It''s allowed to barbecue in the park."],["Spaß machen","Es macht Spaß, zusammen zu kochen.","It''s fun to cook together."]],"highlight_row":-1,"description_de":"Nach jedem Ausdruck kommt ein Komma, dann der Infinitiv mit zu am Ende.","description_en":"After each expression comes a comma, then the zu-group, with the infinitive last. wichtig, schön, schwer, leicht and möglich all work the same way after es ist."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Comma, then zu, then the verb at the very end — every single time.', 'Komma, dann zu, dann das Verb ganz am Ende — immer so.', NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'd35600a6-b14d-5ef4-95be-bcc1b7ffe672'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'f10ed66d-75b2-5a53-8a20-1f4c2372bd00'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'pattern', 'Building the zu-Infinitive and the Comma', 'So bildest du den Infinitiv mit zu', '{"type":"steps","steps":[{"step":1,"title_de":"Bilde den Hauptsatz.","title_en":"Build the main clause.","detail_de":"Ich habe Lust. Es ist wichtig.","detail_en":"Start with the trigger expression alone: Ich habe Lust. Es ist wichtig."},{"step":2,"title_de":"Setze ein Komma.","title_en":"Add a comma.","detail_de":"Ich habe Lust, ...","detail_en":"Before a longer zu-group, a comma marks the boundary: Ich habe Lust, ..."},{"step":3,"title_de":"Formuliere den Infinitiv mit zu.","title_en":"Form zu + the infinitive.","detail_de":"..., ins Kino zu gehen.","detail_en":"zu comes directly before the infinitive, which stands at the very end: ..., ins Kino zu gehen."},{"step":4,"title_de":"Prüfe: trennbares Verb?","title_en":"Check: is it a separable verb?","detail_de":"anrufen -> an-zu-rufen. zu steht zwischen Präfix und Verb.","detail_en":"For a separable verb, zu goes inside, between the prefix and the stem: anrufen -> anzurufen."}],"description_de":"Vier Schritte: Hauptsatz, Komma, zu + Infinitiv am Ende. Bei trennbaren Verben steht zu in der Mitte.","description_en":"Four steps every time: main clause, comma, zu + infinitive at the end — and for separable verbs, zu slots into the middle of the verb."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Comma first, verb last — and zu always sticks right before the infinitive.', 'Komma zuerst, Verb am Ende — und zu steht immer direkt vor dem Infinitiv.', 'You already know the dass-clause: Ich sage, dass ich einkaufe. The zu-infinitive is the shorter option: Ich habe vor, einzukaufen.', 'Du kennst schon den Nebensatz mit dass, zum Beispiel: Ich sage, dass ich einkaufe. Der Infinitiv mit zu ist kürzer: Ich habe vor, einzukaufen.', 'Only one infinitive with zu per clause — the object, time or place words sit between the comma and the zu-verb.', 'Nur ein Infinitiv mit zu pro Satz. Objekt, Zeit oder Ort stehen zwischen Komma und dem zu-Verb.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'f10ed66d-75b2-5a53-8a20-1f4c2372bd00'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'f87e4a6c-1aa4-5fb4-ad2a-6a68f45fd3ad'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'explanation_patterns', 'Separable Verbs with zu: an-zu-rufen', 'Trennbare Verben mit zu: an-zu-rufen', '{"type":"case_table","headers":["Infinitiv","mit zu","Beispiel"],"rows":[["anrufen","anzurufen","Ich vergesse oft, meine Oma anzurufen."],["einkaufen","einzukaufen","Ich habe vor, heute einzukaufen."],["aufräumen","aufzuräumen","Wir fangen an, die Küche aufzuräumen."],["aufstehen","aufzustehen","Es ist schwer, am Montag früh aufzustehen."]],"highlight_row":-1,"description_de":"zu steht mitten im Verb, zwischen Präfix und Stamm — ein Wort, keine Lücke.","description_en":"zu sits inside the separable verb, between the prefix and the stem, written as one word: anzurufen, not zu anrufen or an zu rufen."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, 'Präfix + zu + Verb, alles ein Wort.', 'You know anrufen -> ruft an from Trennbare Verben. With zu, the two parts become one word: anzurufen.', 'Du kennst anrufen -> ruft an aus dem Thema Trennbare Verben. Mit zu wird daraus ein Wort: anzurufen.', 'versuchen (not separable) stays two words: versuchen, zu lernen. anrufen (separable) becomes one word: anzurufen.', 'versuchen ist nicht trennbar: versuchen, zu lernen bleibt zwei Wörter. anrufen ist trennbar: daraus wird ein Wort, anzurufen.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'f87e4a6c-1aa4-5fb4-ad2a-6a68f45fd3ad'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'e828ff49-c91c-5f53-be7f-70ae3f3ec627'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'explanation_exceptions', 'No zu: Modal Verbs and gehen, bleiben, lassen, sehen, hören', 'Kein zu: Modalverben und gehen, bleiben, lassen, sehen, hören', '{"type":"case_table","headers":["Verb","Beispiel ohne zu","Englisch"],"rows":[["gehen","Ich gehe schwimmen.","I''m going swimming."],["bleiben","Er bleibt sitzen.","He stays seated."],["sehen","Ich sehe die Kinder spielen.","I see the children playing."],["hören","Wir hören die Vögel singen.","We hear the birds singing."]],"highlight_row":-1,"description_de":"Diese Verben stehen mit einem bloßen Infinitiv, ganz ohne zu. Genauso bei lassen.","description_en":"These verbs take a bare infinitive, with no zu at all — and modal verbs (müssen, können, wollen, dürfen, sollen, mögen) never take zu either: Ich muss arbeiten, not Ich muss zu arbeiten."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, 'Modalverben und gehen, bleiben, sehen, hören, lassen: nie zu!', 'You know müssen, können and the other modal verbs from Modalverben. That rule never changes: no zu, ever.', 'Du kennst müssen, können und die anderen Modalverben aus Modalverben. Diese Regel ändert sich nie: nie zu.', 'This is the opposite of the topic''s main rule: most verbs on this page NEED zu. These five, plus every modal, never do.', 'Das ist das Gegenteil der Hauptregel. Die meisten Verben hier brauchen zu. Diese fünf und jedes Modalverb brauchen nie ein zu.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'e828ff49-c91c-5f53-be7f-70ae3f3ec627'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'cb29cfed-d268-582b-9c27-94be18b789c9'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'tip', 'Es ist … zu / Ich finde es … zu', 'Es ist … zu / Ich finde es … zu', '{"content_de":"Nach es ist + Adjektiv kommt ein Komma, dann zu + Infinitiv. Bei ich finde es + Adjektiv ist es genauso. Das Adjektiv steht vor dem Komma.","content_en":"After es ist + adjective or ich finde es + adjective, add a comma, then zu + infinitive: Es ist schwer, früh aufzustehen. Ich finde es schön, Freunde zu treffen."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'verboten sein and erlaubt sein work the same way: Es ist verboten, hier zu parken.', 'verboten sein und erlaubt sein funktionieren genauso: Es ist verboten, hier zu parken.', 'Do not confuse this with haben/sein + zu meaning ''has to be done'' — that pattern is B1 and not used here.', 'Verwechsle das nicht mit haben/sein + zu für eine Pflicht. Das kommt erst in B1.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'cb29cfed-d268-582b-9c27-94be18b789c9'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '97f5d6bb-adb0-5a67-8c7c-c4e4686a3ae7'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'dialogue', 'Dialogue: Planning the Weekend by Phone', 'Dialog: das Wochenende am Telefon planen', '{"speakers":["Lena","Tom"],"exchanges":[{"speaker":"Lena","text_de":"Hast du Lust, am Samstag mit mir ins Schwimmbad zu gehen?","text_en":"Do you feel like coming to the pool with me on Saturday?","grammar_note":"Lust haben + zu-Infinitiv (gehen)"},{"speaker":"Tom","text_de":"Ich habe leider keine Zeit, den ganzen Tag weg zu sein.","text_en":"Unfortunately I have no time to be away all day.","grammar_note":"keine Zeit haben + zu-Infinitiv (sein)"},{"speaker":"Lena","text_de":"Schade! Ich habe vergessen, dich früher zu fragen.","text_en":"Too bad! I forgot to ask you earlier.","grammar_note":"vergessen + zu-Infinitiv (fragen)"},{"speaker":"Tom","text_de":"Kein Problem. Ich versuche, am Wochenende Zeit zu finden.","text_en":"No problem. I''ll try to find time on the weekend.","grammar_note":"versuchen + zu-Infinitiv (finden)"},{"speaker":"Lena","text_de":"Gut. Es ist wichtig, auch mal Pause zu machen.","text_en":"Good. It''s important to take a break sometimes too.","grammar_note":"es ist wichtig + zu-Infinitiv (machen)"},{"speaker":"Tom","text_de":"Da hast du recht. Ich habe vor, am Sonntag anzurufen.","text_en":"You''re right. I''m planning to call on Sunday.","grammar_note":"vorhaben + trennbares Verb: anzurufen"},{"speaker":"Lena","text_de":"Perfekt! Ich freue mich schon.","text_en":"Perfect! I''m already looking forward to it.","grammar_note":"Ich freue mich (auf) — bekannte Wendung, kein neuer Infinitiv hier"}],"context_de":"Lena ruft Tom an und plant das Wochenende.","context_en":"Lena calls Tom to plan the weekend.","grammar_focus_en":"Every zu-infinitive here follows a trigger expression from the case table — Lust haben, keine Zeit haben, vergessen, versuchen, es ist wichtig, vorhaben. One of them, anzurufen, is a separable verb with zu inside the word. Sprechen Teil 2-3 rewards exactly this kind of natural back-and-forth about plans."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Hören Teil 1 plays short everyday calls like this one; Sprechen Teil 2-3 asks you to make and react to plans the same way.', 'So klingt ein Alltagsgespräch am Telefon. Sprechen Teil 2-3 verlangt genau solche Pläne und Reaktionen.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '97f5d6bb-adb0-5a67-8c7c-c4e4686a3ae7'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '83925329-74b0-5bae-962d-069e5b9671b0'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'common_mistakes', 'Six Mistakes with zu + Infinitiv', 'Sechs Fehler bei zu + Infinitiv', '{"content_de":"Diese Fehler kommen oft vor. Lies die Beispiele langsam.","content_en":"These mistakes come up again and again. Read the pairs slowly and compare them."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich muss zu arbeiten.","correct":"Ich muss arbeiten.","explanation_de":"Modalverben stehen immer mit bloßem Infinitiv, nie mit zu.","explanation_en":"Modal verbs always take a bare infinitive; they never take zu."},{"wrong":"Ich vergesse zu anrufen meine Mutter.","correct":"Ich vergesse, meine Mutter anzurufen.","explanation_de":"Bei trennbaren Verben kommt zu mitten ins Verb, und das Objekt steht davor.","explanation_en":"With a separable verb, zu goes inside the verb itself, and the object comes before it: meine Mutter anzurufen."},{"wrong":"Ich gehe zu schwimmen.","correct":"Ich gehe schwimmen.","explanation_de":"gehen steht mit bloßem Infinitiv, ganz ohne zu.","explanation_en":"gehen takes a bare infinitive with no zu at all."},{"wrong":"Es ist wichtig pünktlich zu sein.","correct":"Es ist wichtig, pünktlich zu sein.","explanation_de":"Nach es ist wichtig steht immer ein Komma.","explanation_en":"After es ist wichtig the comma is obligatory."},{"wrong":"Ich habe Lust, zu gehen ins Kino.","correct":"Ich habe Lust, ins Kino zu gehen.","explanation_de":"zu + Verb steht ganz am Ende der zu-Gruppe.","explanation_en":"zu + verb goes to the very end of the zu-group."},{"wrong":"Ich habe vor, morgen ein zu kaufen.","correct":"Ich habe vor, morgen einzukaufen.","explanation_de":"einkaufen ist ein trennbares Verb; zu kommt hinein und alles bleibt ein Wort: einzukaufen.","explanation_en":"einkaufen is one separable verb; zu goes inside it and the whole thing stays one word: einzukaufen."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '83925329-74b0-5bae-962d-069e5b9671b0'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'dbaeebfb-2787-5077-b8cf-13562b0bdfe1'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["Nach Lust haben, Zeit haben, vergessen, versuchen, anfangen, aufhören kommt: Komma + zu + Infinitiv.","Auch nach vorhaben und Angst haben kommt: Komma + zu + Infinitiv.","Nach es ist wichtig/schön/schwer/leicht/möglich und ich finde es … kommt auch: Komma + zu + Infinitiv.","verboten sein, erlaubt sein und Spaß machen funktionieren genauso.","Bei trennbaren Verben steht zu in der Mitte, alles ein Wort: anzurufen, einzukaufen, aufzuräumen.","Modalverben nehmen nie zu: Ich muss arbeiten.","gehen, bleiben, sehen, hören und lassen stehen mit bloßem Infinitiv, ohne zu.","Bei einer längeren zu-Gruppe steht ein Komma davor.","um … zu, ohne … zu und statt … zu kommen erst in B1.","Prüfung: SMS-Einladungen und Absagen (Schreiben Teil 1), Sprechen Teil 2-3.","Beispiel: Ich habe keine Zeit, heute einzukaufen."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'dbaeebfb-2787-5077-b8cf-13562b0bdfe1'::uuid);

-- Examples
INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '4f0ad3a2-4bb1-57c3-a1c4-e846e35600e5'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'Könnten Sie mir bitte helfen?', 'Could you help me, please?', 'Könnten', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Könnten is the Konjunktiv II of können for Sie — the standard opener for a polite request.', 'Könnten ist Konjunktiv II von können bei Sie. So beginnt eine höfliche Bitte.', '{"Könnten":"could (können, Konjunktiv II, Sie)","Sie":"you (formal)","mir":"me (Dativ)","bitte":"please","helfen":"to help (infinitive)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '4f0ad3a2-4bb1-57c3-a1c4-e846e35600e5'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '3523e331-1cee-5aaa-829d-95fd960999f6'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'Ich hätte gern einen Kaffee.', 'I would like a coffee.', 'hätte gern', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'hätte gern pairs with a noun, einen Kaffee — never with an infinitive.', 'hätte gern steht vor einem Nomen, hier einen Kaffee.', '{"Ich":"I","hätte":"would have (haben, Konjunktiv II, ich)","gern":"gladly","einen":"a (Akkusativ, maskulin)","Kaffee":"coffee"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '3523e331-1cee-5aaa-829d-95fd960999f6'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '5a1f5fc8-c692-51f7-86f3-686ad3eaae2b'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'Wir könnten am Samstag ins Kino gehen.', 'We could go to the cinema on Saturday.', 'könnten', NULL, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'könnten with wir makes a suggestion; gehen closes the sentence as an infinitive.', 'könnten mit wir macht einen Vorschlag. Der Infinitiv gehen steht am Ende.', '{"Wir":"we","könnten":"could (können, Konjunktiv II, wir)","am":"on the (an + dem)","Samstag":"Saturday","ins":"into the (in + das)","Kino":"cinema","gehen":"to go (infinitive)"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '5a1f5fc8-c692-51f7-86f3-686ad3eaae2b'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '42be167d-fa7c-5f20-89ed-f333240b2cd0'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'Das wäre schön.', 'That would be nice.', 'wäre', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'wäre is the natural reaction to a suggestion — the Konjunktiv II of sein.', 'wäre ist eine typische Reaktion auf einen Vorschlag — Konjunktiv II von sein.', '{"Das":"that","wäre":"would be (sein, Konjunktiv II)","schön":"nice"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '42be167d-fa7c-5f20-89ed-f333240b2cd0'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '974cf444-77a1-5745-aa85-e4d5563b152b'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'Würdest du mir bitte helfen?', 'Would you help me, please?', 'Würdest', NULL, 5, '2026-09-05T12:00:00+00:00'::timestamptz, 'Würdest is würde plus -st for du. helfen stays at the end as an infinitive.', 'Würdest ist würde plus -st bei du. helfen steht als Infinitiv am Ende.', '{"Würdest":"would (werden, Konjunktiv II, du)","du":"you","mir":"me (Dativ)","bitte":"please","helfen":"to help (infinitive)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '974cf444-77a1-5745-aa85-e4d5563b152b'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '1d5a32bf-ebeb-5a90-9839-f4ce091f9af9'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'Wie wäre es mit einem Spaziergang?', 'How about a walk?', 'Wie wäre es mit', NULL, 6, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wie wäre es mit + Dativ is a fixed chunk for making a suggestion.', 'Wie wäre es mit + Dativ ist ein fester Ausdruck für einen Vorschlag.', '{"Wie":"how","wäre":"would be (sein, Konjunktiv II)","es":"it","mit":"with","einem":"a (Dativ, maskulin)","Spaziergang":"walk"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '1d5a32bf-ebeb-5a90-9839-f4ce091f9af9'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '5f0b5c1c-ad48-5770-acc3-da5a22e230d1'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'Ich hätte noch eine Frage.', 'I have one more question.', 'hätte', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'hätte plus eine Frage is a standard opener for a polite question in an e-mail.', 'hätte plus eine Frage ist ein typischer Satz für eine höfliche Frage in der E-Mail.', '{"Ich":"I","hätte":"would have (haben, Konjunktiv II, ich)","noch":"still, one more","eine":"a (Akkusativ, feminin)","Frage":"question"}'::jsonb, 1, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '5f0b5c1c-ad48-5770-acc3-da5a22e230d1'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'e256c781-7741-511a-b4dd-a1e7e5ad2ae8'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'Ihr könntet auch am Sonntag kommen.', 'You could also come on Sunday.', 'könntet', NULL, 8, '2026-09-05T12:00:00+00:00'::timestamptz, 'könntet is the ihr-form: könnte plus the ending -t.', 'könntet ist die ihr-Form: könnte plus die Endung -t.', '{"Ihr":"you (plural)","könntet":"could (können, Konjunktiv II, ihr)","auch":"also","am":"on the (an + dem)","Sonntag":"Sunday","kommen":"to come (infinitive)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'e256c781-7741-511a-b4dd-a1e7e5ad2ae8'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'c889716e-140f-59aa-90c0-b59aa1e93a18'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'Wärst du am Sonntag zu Hause?', 'Would you be home on Sunday?', 'Wärst', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'Wärst is wäre plus -st for du, asking about a plan politely.', 'Wärst ist wäre plus -st bei du. So fragst du höflich nach einem Plan.', '{"Wärst":"would be (sein, Konjunktiv II, du)","du":"you","am":"on the (an + dem)","Sonntag":"Sunday","zu":"at (fixed with Hause)","Hause":"home (zu Hause = at home)"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'c889716e-140f-59aa-90c0-b59aa1e93a18'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '0eabe158-12fd-56fc-a156-4d2b573fe0e6'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 'Wir würden euch gern morgen besuchen.', 'We would like to visit you tomorrow.', 'würden', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'würden gern plus an infinitive expresses a friendly wish or plan.', 'würden gern plus Infinitiv drückt einen freundlichen Wunsch aus.', '{"Wir":"we","würden":"would (werden, Konjunktiv II, wir)","euch":"you (plural, Akkusativ)","gern":"gladly","morgen":"tomorrow","besuchen":"to visit (infinitive)"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '0eabe158-12fd-56fc-a156-4d2b573fe0e6'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '3cbc266a-d517-502b-9dc2-a9d073955ff0'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'Ich warte auf den Bus.', 'I am waiting for the bus.', 'warte auf', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'warten always takes auf + Akkusativ. den Bus is a thing, so the wo(r)-question would be Worauf?', 'warten steht immer mit auf + Akkusativ. den Bus ist eine Sache.', '{"Ich":"I","warte":"wait, am waiting (warten + auf)","auf":"for (fixed preposition with warten, + Akkusativ)","den":"the (Akkusativ, maskulin)","Bus":"bus"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '3cbc266a-d517-502b-9dc2-a9d073955ff0'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '5be7830b-5be5-5f61-b65f-8a7b9e9c993f'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'Worauf wartest du?', 'What are you waiting for?', 'Worauf', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'For things, ask with wo(r)- + preposition: Worauf wartest du? (wo + r + auf, because auf starts with a vowel)', 'Für Sachen fragst du mit wo(r)- + Präposition: Worauf wartest du?', '{"Worauf":"what … for (wo + r + auf, question word for things)","wartest":"are waiting (warten, du-Form)","du":"you"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '5be7830b-5be5-5f61-b65f-8a7b9e9c993f'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '19e7fd68-5325-5854-b2a2-31aa0ae82962'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'Ich warte darauf.', 'I am waiting for it.', 'darauf', NULL, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'For things, answer with da(r)- + preposition: darauf, never auf es.', 'Für Sachen antwortest du mit da(r)- + Präposition: darauf, nicht auf es.', '{"Ich":"I","warte":"am waiting (warten)","darauf":"for it (da + r + auf, replaces auf + a thing)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '19e7fd68-5325-5854-b2a2-31aa0ae82962'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '6278970d-2d8e-5ea3-9b78-ceee7e2170cb'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'Wir freuen uns auf den Sommerurlaub.', 'We are looking forward to the summer holiday.', 'freuen uns auf', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'sich freuen auf + Akkusativ is used for something still ahead — the joy is in the future.', 'sich freuen auf + Akkusativ: die Freude ist noch in der Zukunft.', '{"Wir":"we","freuen":"look forward (sich freuen + auf, reflexive)","uns":"ourselves (reflexive pronoun, wir)","auf":"for, to (fixed preposition, + Akkusativ)","den":"the (Akkusativ, maskulin)","Sommerurlaub":"summer holiday"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '6278970d-2d8e-5ea3-9b78-ceee7e2170cb'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '0eb06720-4caa-52f9-a7b5-69daed8c951e'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'Er freut sich über das Geschenk.', 'He is happy about the present.', 'freut sich über', NULL, 5, '2026-09-05T12:00:00+00:00'::timestamptz, 'sich freuen über + Akkusativ is for something already happening — not a future event.', 'sich freuen über + Akkusativ: die Freude ist schon da, nicht in der Zukunft.', '{"Er":"he","freut":"is happy (sich freuen + über, reflexive, er-Form)","sich":"himself (reflexive pronoun, er)","über":"about (fixed preposition, + Akkusativ)","das":"the (Akkusativ, neutrum)","Geschenk":"present, gift"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '0eb06720-4caa-52f9-a7b5-69daed8c951e'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'b304f77c-3f06-5645-a5de-62ff75ad1981'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'Ich interessiere mich für Musik.', 'I am interested in music.', 'interessiere mich für', NULL, 6, '2026-09-05T12:00:00+00:00'::timestamptz, 'sich interessieren für + Akkusativ says what interests you.', 'sich interessieren für + Akkusativ: du sagst, was dich interessiert.', '{"Ich":"I","interessiere":"am interested (sich interessieren + für, ich-Form)","mich":"myself (reflexive pronoun, ich)","für":"in (fixed preposition, + Akkusativ)","Musik":"music"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'b304f77c-3f06-5645-a5de-62ff75ad1981'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '7bcb11cf-34ea-550a-bc13-0aa6188dcd69'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'Sie denkt an ihren Urlaub.', 'She is thinking about her holiday.', 'denkt an', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'denken an + Akkusativ; here der Urlaub is a thing, so the wo(r)-question would be Woran denkt sie?', 'denken an + Akkusativ: hier ist der Urlaub eine Sache.', '{"Sie":"she","denkt":"thinks (denken + an, sie-Form)","an":"about (fixed preposition, + Akkusativ)","ihren":"her (Akkusativ, maskulin)","Urlaub":"holiday, vacation"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '7bcb11cf-34ea-550a-bc13-0aa6188dcd69'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'ca9c31a9-7d8e-5773-aed4-d8eb414455b2'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'Ich denke an meinen Bruder.', 'I am thinking about my brother.', 'denke an', NULL, 8, '2026-09-05T12:00:00+00:00'::timestamptz, 'For people you never use wo(r)- — ask with the preposition + wen: An wen denkst du?', 'Bei Personen fragst du nicht mit wo(r)-, sondern mit an + wen: An wen denkst du?', '{"Ich":"I","denke":"am thinking (denken + an, ich-Form)","an":"about (fixed preposition, + Akkusativ)","meinen":"my (Akkusativ, maskulin)","Bruder":"brother"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'ca9c31a9-7d8e-5773-aed4-d8eb414455b2'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'ff90becd-5030-5d21-b40b-fe433e27419f'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'Wir sprechen über das Wetter.', 'We are talking about the weather.', 'sprechen über', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'sprechen über + Akkusativ names the topic of the conversation.', 'sprechen über + Akkusativ: das Thema im Gespräch.', '{"Wir":"we","sprechen":"are talking (sprechen + über)","über":"about (fixed preposition, + Akkusativ)","das":"the (Akkusativ, neutrum)","Wetter":"weather"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'ff90becd-5030-5d21-b40b-fe433e27419f'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '1a6df9a6-996c-5446-b740-0ec496069540'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 'Ich spreche mit meiner Chefin.', 'I am talking to my boss.', 'spreche mit', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'sprechen mit + Dativ names the person you are talking to — a different preposition and case from sprechen über.', 'sprechen mit + Dativ: du nennst die Person. sprechen über + Akkusativ: du nennst das Thema.', '{"Ich":"I","spreche":"am talking (sprechen + mit)","mit":"to, with (fixed preposition, + Dativ)","meiner":"my (Dativ, feminin)","Chefin":"(female) boss"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '1a6df9a6-996c-5446-b740-0ec496069540'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'a24f6596-d2df-57f5-9ef5-9242b3d70970'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'Wissen Sie, ob die Bank heute geöffnet hat?', 'Do you know whether the bank is open today?', 'ob die Bank heute geöffnet hat', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'ob replaces the yes/no question Hat die Bank heute geöffnet?; the verb hat closes the clause.', 'ob ersetzt die Ja/Nein-Frage Hat die Bank heute geöffnet? Das Verb hat steht am Ende.', '{"Wissen":"do you know (wissen, Sie-Form)","Sie":"you (formal)","ob":"whether, if","die":"the (feminine)","Bank":"bank","heute":"today","geöffnet":"opened (Partizip II of öffnen)","hat":"has (haben, Präsens, sie)"}'::jsonb, 2, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'a24f6596-d2df-57f5-9ef5-9242b3d70970'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'ad13ee90-8175-5e69-9e77-49ec7333f432'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'Können Sie mir sagen, wo der Bahnhof ist?', 'Can you tell me where the train station is?', 'wo der Bahnhof ist', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'wo stays the same word; only the verb ist moves to the end of the clause.', 'wo bleibt gleich. Nur das Verb ist wandert ganz ans Ende.', '{"Können":"can (können, Sie-Form)","Sie":"you (formal)","mir":"me (Dativ)","sagen":"to say, tell (infinitive)","wo":"where","der":"the (masculine)","Bahnhof":"train station","ist":"is (sein, Präsens, er/sie/es)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'ad13ee90-8175-5e69-9e77-49ec7333f432'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'eadb1106-5822-5468-aa2c-cddb21fe40db'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'Weißt du, wann der Bus kommt?', 'Do you know when the bus is coming?', 'wann der Bus kommt', NULL, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The direct question Wann kommt der Bus? keeps its W-word wann; the verb kommt moves to the end.', 'Die direkte Frage Wann kommt der Bus? behält wann. Das Verb kommt wandert ans Ende.', '{"Weißt":"do you know (wissen, du-Form)","du":"you","wann":"when","der":"the (masculine)","Bus":"bus","kommt":"comes, is coming (kommen, Präsens, er/sie/es)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'eadb1106-5822-5468-aa2c-cddb21fe40db'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '892b931a-7ff6-598c-9d5f-41fe417c8658'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'Ich weiß nicht, was ich mitbringen muss.', 'I don''t know what I have to bring.', 'was ich mitbringen muss', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'With a modal verb the infinitive mitbringen comes first and the modal muss closes the clause.', 'Bei einem Modalverb steht der Infinitiv mitbringen zuerst, das Modalverb muss ganz am Ende.', '{"Ich":"I","weiß":"know (wissen, Präsens, ich)","nicht":"not","was":"what","ich":"I","mitbringen":"to bring along (separable infinitive)","muss":"have to (müssen, Präsens, ich)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '892b931a-7ff6-598c-9d5f-41fe417c8658'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'ccdf01d6-00fd-529d-9526-6aa55f93d442'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'Ich habe keine Ahnung, wer heute im Büro ist.', 'I have no idea who is in the office today.', 'wer heute im Büro ist', NULL, 5, '2026-09-05T12:00:00+00:00'::timestamptz, 'heute stays inside the clause, before the final verb ist.', 'heute bleibt im Nebensatz, vor dem Verb ist.', '{"Ich":"I","habe":"have (haben, Präsens, ich)","keine":"no, not any","Ahnung":"idea, clue","wer":"who","heute":"today","im":"in the (in + dem)","Büro":"office","ist":"is (sein, Präsens, er/sie/es)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'ccdf01d6-00fd-529d-9526-6aa55f93d442'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '7c6007fe-3e12-5b0e-b7c0-51ad68825158'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'Ich frage mich, warum der Kurs so teuer ist.', 'I wonder why the course is so expensive.', 'warum der Kurs so teuer ist', NULL, 6, '2026-09-05T12:00:00+00:00'::timestamptz, 'Ich frage mich is a statement frame, so the sentence ends in a period.', 'Ich frage mich ist ein Aussage-Rahmen. Der Satz endet mit einem Punkt.', '{"Ich":"I","frage":"ask (fragen, Präsens, ich)","mich":"myself (reflexive, Akkusativ)","warum":"why","der":"the (masculine)","Kurs":"course","so":"so","teuer":"expensive","ist":"is (sein, Präsens, er/sie/es)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '7c6007fe-3e12-5b0e-b7c0-51ad68825158'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'fb4460d2-3704-54fe-b5e8-48dfa393a492'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'Können Sie mir sagen, wie viel die Fahrkarte kostet?', 'Can you tell me how much the ticket costs?', 'wie viel die Fahrkarte kostet', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'wie viel is two words and stays at the front; the verb kostet moves to the end.', 'wie viel besteht aus zwei Wörtern und bleibt vorn. Das Verb kostet wandert ans Ende.', '{"Können":"can (können, Sie-Form)","Sie":"you (formal)","mir":"me (Dativ)","sagen":"to say, tell (infinitive)","wie":"how","viel":"much","die":"the (feminine)","Fahrkarte":"ticket","kostet":"costs (kosten, Präsens, es/sie)"}'::jsonb, 3, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'fb4460d2-3704-54fe-b5e8-48dfa393a492'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'e191bddf-63ba-5fff-8701-f26463b2c31d'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'Ich möchte wissen, wie lange die Prüfung dauert.', 'I would like to know how long the exam lasts.', 'wie lange die Prüfung dauert', NULL, 8, '2026-09-05T12:00:00+00:00'::timestamptz, 'wie lange asks about duration; the verb dauert closes the clause.', 'wie lange fragt nach der Dauer. Das Verb dauert steht am Ende.', '{"Ich":"I","möchte":"would like (möchte, Präsens, ich)","wissen":"to know (infinitive)","wie":"how","lange":"long","die":"the (feminine)","Prüfung":"exam, test","dauert":"lasts (dauern, Präsens, es/sie)"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'e191bddf-63ba-5fff-8701-f26463b2c31d'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '8294e790-5564-545c-9172-ca173b7754a9'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'Wissen Sie, welches Formular ich ausfüllen muss?', 'Do you know which form I have to fill out?', 'welches Formular ich ausfüllen muss', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'welches agrees with the neuter noun Formular; the infinitive ausfüllen comes before the modal muss at the very end.', 'welches richtet sich nach dem Neutrum Formular. Der Infinitiv ausfüllen steht vor dem Modalverb muss ganz am Ende.', '{"Wissen":"do you know (wissen, Sie-Form)","Sie":"you (formal)","welches":"which (neuter, Akkusativ)","Formular":"form","ich":"I","ausfüllen":"to fill out (separable infinitive)","muss":"have to (müssen, Präsens, ich)"}'::jsonb, 3, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '8294e790-5564-545c-9172-ca173b7754a9'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '62c8609a-7e2c-50c2-a95f-ce725ff8a86e'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 'Ich weiß nicht, mit wem ich sprechen soll.', 'I don''t know who I should talk to.', 'mit wem ich sprechen soll', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'For a person after a fixed preposition, German says mit wem, not a wo(r)-compound.', 'Bei einer Person nach einer festen Präposition sagt man mit wem, kein wo(r)-Wort.', '{"Ich":"I","weiß":"know (wissen, Präsens, ich)","nicht":"not","mit":"with","wem":"whom (Dativ)","ich":"I","sprechen":"to speak (infinitive)","soll":"should (sollen, Präsens, ich)"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '62c8609a-7e2c-50c2-a95f-ce725ff8a86e'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '31bf5688-fc10-5211-a4c7-c261a6336b16'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'Hast du Lust, heute Abend ins Kino zu gehen?', 'Do you feel like going to the cinema tonight?', 'zu gehen', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Lust haben is followed by a comma, then zu + gehen at the end of the clause.', 'Nach Lust haben kommt ein Komma, dann zu gehen am Ende.', '{"Hast":"do (you) have (haben, question, du)","du":"you","Lust":"desire, mood (Lust haben = to feel like)","heute":"today","Abend":"evening (heute Abend = tonight)","ins":"into the (in + das)","Kino":"cinema","zu":"to (zu + infinitive)","gehen":"to go (infinitive)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '31bf5688-fc10-5211-a4c7-c261a6336b16'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'a702f78b-3a0a-52cf-85d1-7ed212f69cec'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'Ich habe keine Zeit, mit dir Kaffee zu trinken.', 'I have no time to drink coffee with you.', 'zu trinken', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'keine Zeit haben works just like Lust haben: comma, then the zu-group at the end.', 'keine Zeit haben funktioniert wie Lust haben: Komma, dann der zu-Infinitiv am Ende.', '{"Ich":"I","habe":"have (haben, ich)","keine":"no, not any (Akkusativ, feminin)","Zeit":"time","mit":"with","dir":"you (Dativ)","Kaffee":"coffee","zu":"to","trinken":"to drink (infinitive)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'a702f78b-3a0a-52cf-85d1-7ed212f69cec'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '16429b01-7687-57c3-9bd7-a21f51cd6fd8'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'Ich habe vergessen, meine Mutter anzurufen.', 'I forgot to call my mother.', 'anzurufen', NULL, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'anrufen is separable, so zu slots inside it: anzurufen, one word.', 'anrufen ist trennbar, deshalb steht zu mitten im Wort: anzurufen.', '{"Ich":"I","habe":"have (haben, Perfekt-Hilfsverb)","vergessen":"forgotten (vergessen, Partizip II)","meine":"my (Akkusativ, feminin)","Mutter":"mother","anzurufen":"to call (separable verb anrufen with zu: an-zu-rufen)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '16429b01-7687-57c3-9bd7-a21f51cd6fd8'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '0ac8372c-d66d-5391-b885-d0a47f000bc9'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'Ich versuche, jeden Tag Deutsch zu lernen.', 'I try to learn German every day.', 'zu lernen', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'versuchen is not separable, so zu simply stands in front of lernen.', 'versuchen ist nicht trennbar, deshalb steht zu einfach vor lernen.', '{"Ich":"I","versuche":"try (versuchen, ich)","jeden":"every (Akkusativ, maskulin)","Tag":"day","Deutsch":"German","zu":"to","lernen":"to learn (infinitive)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '0ac8372c-d66d-5391-b885-d0a47f000bc9'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '50043a41-f24f-524b-862a-d7a4f72675cc'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'Wir fangen an, das Zimmer aufzuräumen.', 'We are starting to tidy up the room.', 'aufzuräumen', NULL, 5, '2026-09-05T12:00:00+00:00'::timestamptz, 'anfangen itself is separable (fangen … an), and its own zu-clause holds a second separable verb, aufzuräumen.', 'anfangen ist selbst trennbar (fangen … an), und im zu-Satz steckt noch ein trennbares Verb: aufzuräumen.', '{"Wir":"we","fangen":"start (anfangen, wir)","an":"(separable prefix of anfangen, here at the end of the main clause)","das":"the (neutral, Akkusativ)","Zimmer":"room","aufzuräumen":"to tidy up (separable verb aufräumen with zu: auf-zu-räumen)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '50043a41-f24f-524b-862a-d7a4f72675cc'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'f506c4b2-dd2e-5be1-bc86-eaede3d67aaf'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'Er hat aufgehört, Zigaretten zu rauchen.', 'He has stopped smoking cigarettes.', 'zu rauchen', NULL, 6, '2026-09-05T12:00:00+00:00'::timestamptz, 'aufhören is in the Perfekt (hat aufgehört); its zu-clause still needs only a comma and zu + infinitive.', 'aufhören steht im Perfekt (hat aufgehört); der zu-Satz braucht trotzdem nur Komma und zu + Infinitiv.', '{"Er":"he","hat":"has (haben, Perfekt-Hilfsverb)","aufgehört":"stopped (aufhören, Partizip II)","Zigaretten":"cigarettes","zu":"to","rauchen":"to smoke (infinitive)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'f506c4b2-dd2e-5be1-bc86-eaede3d67aaf'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '23165c0d-3277-59ce-b208-80b0b1653531'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'Ich habe vor, am Wochenende einzukaufen.', 'I''m planning to go shopping on the weekend.', 'einzukaufen', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'vorhaben (ich habe vor) is followed by a comma and the separable verb einkaufen with zu inside: einzukaufen.', 'Nach vorhaben (ich habe vor) kommt ein Komma und das trennbare Verb einkaufen mit zu: einzukaufen.', '{"Ich":"I","habe":"have (vorhaben: ich habe vor = I plan)","vor":"(separable prefix of vorhaben, here at the end of the main clause)","am":"on the (an + dem)","Wochenende":"weekend","einzukaufen":"to shop (separable verb einkaufen with zu: ein-zu-kaufen)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '23165c0d-3277-59ce-b208-80b0b1653531'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'c0f0c6a9-cd79-5cd9-ac0a-5c77f16db270'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'Sie hat Angst, nachts allein spazieren zu gehen.', 'She''s afraid to go for a walk alone at night.', 'zu gehen', NULL, 8, '2026-09-05T12:00:00+00:00'::timestamptz, 'Angst haben triggers the same pattern; spazieren gehen is a fixed pair, and zu attaches only to gehen.', 'Angst haben löst dasselbe Muster aus. spazieren gehen ist ein festes Paar, und zu steht nur bei gehen.', '{"Sie":"she","hat":"has (haben, sie)","Angst":"fear (Angst haben = to be afraid)","nachts":"at night","allein":"alone","spazieren":"for a walk (spazieren gehen = to go for a walk)","zu":"to","gehen":"to go (infinitive)"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'c0f0c6a9-cd79-5cd9-ac0a-5c77f16db270'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '3c6adc4a-91cb-5dc9-8e73-0279c8fb7dd5'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'Es ist wichtig, pünktlich zu sein.', 'It''s important to be on time.', 'zu sein', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'es ist + adjective takes the same comma + zu + infinitive pattern as the verb expressions.', 'es ist + Adjektiv nimmt dasselbe Muster: Komma, dann zu + Infinitiv.', '{"Es":"it (impersonal subject)","ist":"is (sein, es)","wichtig":"important","pünktlich":"punctual, on time","zu":"to","sein":"to be (infinitive)"}'::jsonb, 2, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '3c6adc4a-91cb-5dc9-8e73-0279c8fb7dd5'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '72260197-c6c4-5cbe-b7e3-83fb94ced26a'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 'Ich finde es schwer, früh aufzustehen.', 'I find it hard to get up early.', 'aufzustehen', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'ich finde es + adjective behaves like es ist + adjective; aufstehen is separable, so zu goes inside: aufzustehen.', 'ich finde es + Adjektiv funktioniert wie es ist + Adjektiv. aufstehen ist trennbar, zu kommt hinein: aufzustehen.', '{"Ich":"I","finde":"find (finden, ich)","es":"it (placeholder object)","schwer":"hard, difficult","früh":"early","aufzustehen":"to get up (separable verb aufstehen with zu: auf-zu-stehen)"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '72260197-c6c4-5cbe-b7e3-83fb94ced26a'::uuid);

-- Exercises
INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'de186c58-82b6-5cd2-9cdd-eefa74ced96d'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 4, 'fill_blank', 'Ich ___ gern einen Tee. (haben, Konjunktiv II, ich)', 'Fill in the polite form: I would like a tea. (verb: haben, Konjunktiv II, ich)', NULL, 'hätte', '["hätte"]'::jsonb, 'hätte is haben plus an Umlaut — the ich-form takes no extra ending.', 'hätte ist haben plus Umlaut. Die ich-Form hat keine Endung.', NULL, 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'hätte gern pairs with the noun einen Tee, not with an infinitive.', 'hätte gern steht vor dem Nomen einen Tee, nicht vor einem Infinitiv.', 'Four Uses: Bitten, Wünsche, Vorschläge, Reaktion'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'de186c58-82b6-5cd2-9cdd-eefa74ced96d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'eef0fe8c-a793-53df-8b5d-4219ef61ca23'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 4, 'fill_blank', '___ du mir bitte dein Heft geben? (werden, Konjunktiv II, du)', 'Fill in the polite form at the start of the question: Would you give me your notebook, please? (verb: werden, Konjunktiv II, du)', NULL, 'Würdest', '["Würdest","würdest"]'::jsonb, 'würde plus -st gives the du-form: Würdest. geben stays an infinitive at the end.', 'würde plus -st ergibt die du-Form: Würdest. geben bleibt Infinitiv am Ende.', NULL, 2, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'A question with a polite du-request opens with the Konjunktiv II form.', 'Eine höfliche Bitte mit du beginnt mit der Konjunktiv-II-Form.', 'The Four Polite Forms'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'eef0fe8c-a793-53df-8b5d-4219ef61ca23'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c531b3f8-5ccb-523f-bd44-63f1ce3902e5'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 4, 'multiple_choice', 'Er ___ gern einen Kaffee. (Funktion: Wunsch vor einem Nomen)', 'Which verb fits before a noun? He would like a coffee. (choose the right form: hätte, würde, wäre or könnte — er)', '["hätte","würde","wäre","könnte"]'::jsonb, 'hätte', NULL, 'einen Kaffee is a noun, so hätte gern fits. würde needs an infinitive, wäre reacts to a suggestion, könnte offers ability.', 'einen Kaffee ist ein Nomen, dazu passt hätte gern. würde braucht einen Infinitiv, wäre ist eine Reaktion, könnte bietet Hilfe an.', NULL, 3, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only hätte gern pairs directly with a bare noun like einen Kaffee.', 'Nur hätte gern steht direkt vor einem Nomen wie einen Kaffee.', 'möchte, hätte gern, würde gern: How They Differ'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c531b3f8-5ccb-523f-bd44-63f1ce3902e5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'cafc514a-3a21-5924-afef-1ba2dfed4269'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 4, 'fill_blank', 'Wir ___ am Samstag ins Museum gehen. (können, Konjunktiv II, wir)', 'Fill in the polite form: We could go to the museum on Saturday. (verb: können, Konjunktiv II, wir)', NULL, 'könnten', '["könnten"]'::jsonb, 'könnten is the wir-form: können plus Umlaut plus -en.', 'könnten ist die wir-Form: können plus Umlaut plus -en.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'könnten with wir makes a friendly suggestion; gehen closes the sentence.', 'könnten mit wir macht einen freundlichen Vorschlag. gehen steht am Ende.', 'Dialogue: Planning the Weekend'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'cafc514a-3a21-5924-afef-1ba2dfed4269'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3a3a043b-2459-56bb-a102-c65338ae3f65'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 4, 'multiple_choice', '___ ihr am Sonntag Zeit? (haben, Konjunktiv II, ihr)', 'Which form is correct? Would you (pl.) have time on Sunday? (verb: haben, Konjunktiv II, ihr)', '["Hättet","Habt","Hattet","Hätten"]'::jsonb, 'Hättet', NULL, 'The ihr-form is Hättet: hätte plus the ihr-ending -t.', 'Die ihr-Form ist Hättet: hätte plus die Endung -t.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Habt is present, Hattet is plain past, Hätten is the wir/sie-form.', 'Habt ist Gegenwart, Hattet ist Präteritum, Hätten ist die wir/sie-Form.', 'Four Uses: Bitten, Wünsche, Vorschläge, Reaktion'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3a3a043b-2459-56bb-a102-c65338ae3f65'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e48b660d-ae14-5411-96ab-507114ef3206'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 4, 'fill_blank', 'Meine Freunde ___ gern mitkommen. (werden, Konjunktiv II, sie)', 'Fill in the polite form: My friends would like to come along. (verb: werden, Konjunktiv II, sie/plural)', NULL, 'würden', '["würden"]'::jsonb, 'würden is the sie-form: würde plus -n. würden gern plus an infinitive expresses a wish.', 'würden ist die sie-Form: würde plus -n. würden gern plus Infinitiv drückt einen Wunsch aus.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'würden gern names a real wish to join in, with mitkommen as the infinitive at the end.', 'würden gern nennt einen echten Wunsch. mitkommen steht am Ende.', 'The Four Polite Forms'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e48b660d-ae14-5411-96ab-507114ef3206'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '181f2528-f2b0-5194-99a8-048b9032c71b'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 4, 'fill_blank', '___ Sie mir bitte die Uhrzeit sagen? (können, Konjunktiv II, Sie)', 'Fill in the polite form at the start of the formal question: Could you tell me the time, please? (verb: können, Konjunktiv II, Sie)', NULL, 'Könnten', '["Könnten","könnten"]'::jsonb, 'Könnten Sie …? is the standard polite request to a stranger or an office.', 'Könnten Sie …? ist die Standard-Bitte an eine fremde Person oder ein Amt.', NULL, 7, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Sie takes the same form as wir: könnten.', 'Sie nimmt die gleiche Form wie wir: könnten.', 'Polite Requests in a Semi-Formal E-Mail'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '181f2528-f2b0-5194-99a8-048b9032c71b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '78d7ac16-72ee-52de-aa0c-5b409e02115c'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 4, 'fill_blank', 'Ich ___ gern ins Kino gehen. (werden, Konjunktiv II, ich)', 'Fill in the polite form: I would like to go to the cinema. (verb: werden, Konjunktiv II, ich)', NULL, 'würde', '["würde"]'::jsonb, 'würde gern plus an infinitive (gehen) expresses a wish — the ich-form takes no extra ending.', 'würde gern plus Infinitiv (gehen) drückt einen Wunsch aus. Die ich-Form hat keine Endung.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Before an infinitive you need würde gern, not hätte gern.', 'Vor einem Infinitiv brauchst du würde gern, nicht hätte gern.', 'möchte, hätte gern, würde gern: How They Differ'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '78d7ac16-72ee-52de-aa0c-5b409e02115c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4cd31bc9-4d7e-5033-9d4e-19d1db6f0911'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 4, 'fill_blank', '___ du mir dein Buch geben? (können, Konjunktiv II, du)', 'Fill in the polite form at the start of the question: Could you give me your book? (verb: können, Konjunktiv II, du)', NULL, 'Könntest', '["Könntest","könntest"]'::jsonb, 'Könntest is könnte plus -st for du.', 'Könntest ist könnte plus -st bei du.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'geben stays an infinitive at the end, after Könntest du mir dein Buch.', 'geben bleibt Infinitiv am Ende, nach Könntest du mir dein Buch.', 'The Four Polite Forms'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4cd31bc9-4d7e-5033-9d4e-19d1db6f0911'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '00711fb8-56ca-5aba-91eb-84e418a435ce'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 4, 'multiple_choice', 'Das ___ nett. (sein, Konjunktiv II)', 'Which form is correct as a reaction? That would be kind. (verb: sein, Konjunktiv II)', '["wäre","ist","war","wären"]'::jsonb, 'wäre', NULL, 'wäre is the natural reaction to a suggestion — the Konjunktiv II of sein.', 'wäre ist eine typische Reaktion auf einen Vorschlag — Konjunktiv II von sein.', NULL, 10, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'ist is present, war is plain past, and wären is the wir/sie-form.', 'ist ist Gegenwart, war ist Präteritum, wären ist die wir/sie-Form.', 'Four Uses: Bitten, Wünsche, Vorschläge, Reaktion'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '00711fb8-56ca-5aba-91eb-84e418a435ce'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '33b3ff92-3748-5e6f-a387-79b9537249db'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 4, 'multiple_choice', 'Wir ___ auch dabei. (sein, Konjunktiv II, wir)', 'Which form is correct? We would also be there. (verb: sein, Konjunktiv II, wir)', '["wären","waren","sind","wärt"]'::jsonb, 'wären', NULL, 'wären is the wir-form: wäre plus -n.', 'wären ist die wir-Form: wäre plus -n.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'waren is plain past, sind is present, and wärt is the ihr-form.', 'waren ist Präteritum, sind ist Gegenwart, wärt ist die ihr-Form.', 'The Four Polite Forms'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '33b3ff92-3748-5e6f-a387-79b9537249db'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '08f88913-7506-5124-a31d-b79d25d3c625'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 4, 'fill_blank', 'Ihr ___ auch morgen kommen. (können, Konjunktiv II, ihr)', 'Fill in the polite form: You (pl.) could also come tomorrow. (verb: können, Konjunktiv II, ihr)', NULL, 'könntet', '["könntet"]'::jsonb, 'könntet is the ihr-form: könnte plus -t.', 'könntet ist die ihr-Form: könnte plus -t.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'könntet makes a friendly, open suggestion; kommen closes the sentence.', 'könntet macht einen freundlichen, offenen Vorschlag. kommen steht am Ende.', 'Dialogue: Planning the Weekend'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '08f88913-7506-5124-a31d-b79d25d3c625'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8fd6cf63-619c-5af8-82dd-888583bb7a9c'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 4, 'error_correction', 'Finde den Fehler: Ich würde gern einen Saft.', 'Correct the sentence two ways: swap the verb, or keep würde and add an infinitive. (I would like a juice.)', NULL, 'Ich hätte gern einen Saft.', '["Ich hätte gern einen Saft.","Ich hätte gern einen Saft","Ich würde gern einen Saft trinken.","Ich würde gern einen Saft trinken"]'::jsonb, 'würde gern needs an infinitive at the end; either swap to hätte gern before the bare noun, or keep würde gern and add trinken.', 'würde gern braucht einen Infinitiv am Ende. Entweder hätte gern vor dem Nomen, oder würde gern plus trinken.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'hätte gern pairs directly with the noun einen Saft; würde gern needs trinken to be complete.', 'hätte gern steht direkt vor dem Nomen einen Saft. würde gern braucht dafür trinken.', 'Common Mistakes with the Polite Forms'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8fd6cf63-619c-5af8-82dd-888583bb7a9c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7b2cb169-e067-56d2-8cf5-fb12aeff6c57'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / euch / gern / besuchen / werden]', 'Write the sentence: We would like to visit you (pl.). (werden → Konjunktiv II, wir; start with Wir)', NULL, 'Wir würden euch gern besuchen.', '["Wir würden euch gern besuchen.","Wir würden euch gern besuchen"]'::jsonb, 'werden becomes würden for wir; besuchen stays an infinitive at the end.', 'Aus werden wird würden bei wir. besuchen bleibt Infinitiv am Ende.', NULL, 1, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'gern stands directly before the infinitive, as in würde gern kommen.', 'gern steht direkt vor dem Infinitiv, wie bei würde gern kommen.', 'möchte, hätte gern, würde gern: How They Differ'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7b2cb169-e067-56d2-8cf5-fb12aeff6c57'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6001dfc1-5e2f-5ac9-9759-91765bc06d65'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 5, 'sentence_building', 'Schreib die Frage: [ihr / gern / mitkommen / werden]', 'Write the question: Would you (pl.) like to come along? (werden → Konjunktiv II, ihr; start with the verb)', NULL, 'Würdet ihr gern mitkommen?', '["Würdet ihr gern mitkommen?","Würdet ihr gern mitkommen"]'::jsonb, 'werden becomes Würdet for ihr; the question opens with the verb.', 'Aus werden wird Würdet bei ihr. Die Frage beginnt mit dem Verb.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'mitkommen is a separable verb and stays whole at the end.', 'mitkommen ist ein trennbares Verb und bleibt als ein Wort am Ende.', 'The Four Polite Forms'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6001dfc1-5e2f-5ac9-9759-91765bc06d65'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4746e7da-7758-544f-8a5f-45338e27a514'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 5, 'sentence_building', 'Schreib den Satz: [er / gern / ins Kino / gehen / werden]', 'Write the sentence: He would like to go to the cinema. (werden → Konjunktiv II, er; start with Er)', NULL, 'Er würde gern ins Kino gehen.', '["Er würde gern ins Kino gehen.","Er würde gern ins Kino gehen"]'::jsonb, 'werden becomes würde for er, the same form as ich.', 'Aus werden wird würde bei er, genau wie bei ich.', NULL, 3, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'gehen stays an infinitive at the very end, after ins Kino.', 'gehen bleibt Infinitiv ganz am Ende, nach ins Kino.', 'möchte, hätte gern, würde gern: How They Differ'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4746e7da-7758-544f-8a5f-45338e27a514'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd0db8f00-7d4f-5a57-9df1-d5ac67e37c91'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / dir / helfen / können]', 'Write the sentence: I could help you. (können → Konjunktiv II, ich; start with Ich)', NULL, 'Ich könnte dir helfen.', '["Ich könnte dir helfen.","Ich könnte dir helfen"]'::jsonb, 'können becomes könnte for ich; the ich-form takes no extra ending.', 'Aus können wird könnte bei ich. Die ich-Form hat keine Endung.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The pronoun dir stands before the infinitive helfen at the end.', 'Das Pronomen dir steht vor dem Infinitiv helfen am Ende.', 'Four Uses: Bitten, Wünsche, Vorschläge, Reaktion'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd0db8f00-7d4f-5a57-9df1-d5ac67e37c91'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '27b4ad09-e882-5893-b058-596a1e650f12'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 5, 'sentence_building', 'Schreib den Satz: [er / uns / helfen / können]', 'Write the sentence: He could help us. (können → Konjunktiv II, er; start with Er)', NULL, 'Er könnte uns helfen.', '["Er könnte uns helfen.","Er könnte uns helfen"]'::jsonb, 'können becomes könnte for er, identical to the ich-form.', 'Aus können wird könnte bei er, genau wie bei ich.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'uns comes before the infinitive helfen at the end.', 'uns steht vor dem Infinitiv helfen am Ende.', 'The Four Polite Forms'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '27b4ad09-e882-5893-b058-596a1e650f12'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6f66a220-1326-5c0f-b5f6-5c0f896bf742'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 5, 'sentence_building', 'Schreib die Frage: [du / morgen / Zeit / haben]', 'Write the question: Would you have time tomorrow? (haben → Konjunktiv II, du; start with the verb)', NULL, 'Hättest du morgen Zeit?', '["Hättest du morgen Zeit?","Hättest du morgen Zeit"]'::jsonb, 'haben becomes Hättest for du; the question opens with the verb.', 'Aus haben wird Hättest bei du. Die Frage beginnt mit dem Verb.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'This polite question sounds softer than the present-tense Hast du morgen Zeit?', 'Diese höfliche Frage klingt weicher als Hast du morgen Zeit?', 'Four Uses: Bitten, Wünsche, Vorschläge, Reaktion'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6f66a220-1326-5c0f-b5f6-5c0f896bf742'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e4f0d25d-20cb-5020-a8fc-4e539016d12e'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / gern / ein Eis / haben]', 'Write the sentence: We would like an ice cream. (haben → Konjunktiv II, wir; start with Wir)', NULL, 'Wir hätten gern ein Eis.', '["Wir hätten gern ein Eis.","Wir hätten gern ein Eis"]'::jsonb, 'haben becomes hätten for wir, paired with the noun ein Eis.', 'Aus haben wird hätten bei wir, zusammen mit dem Nomen ein Eis.', NULL, 7, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'hätten gern pairs with a noun, not with an infinitive.', 'hätten gern steht vor einem Nomen, nicht vor einem Infinitiv.', 'Four Uses: Bitten, Wünsche, Vorschläge, Reaktion'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e4f0d25d-20cb-5020-a8fc-4e539016d12e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ea71c49c-4f5d-5aea-b9c0-c381d07b35d2'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 5, 'sentence_building', 'Schreib die Frage: [Sie / einen Moment / Zeit / haben]', 'Write the polite question: Would you (formal) have a moment of time? (haben → Konjunktiv II, Sie; start with the verb)', NULL, 'Hätten Sie einen Moment Zeit?', '["Hätten Sie einen Moment Zeit?","Hätten Sie einen Moment Zeit"]'::jsonb, 'haben becomes Hätten for Sie, the same form as wir.', 'Aus haben wird Hätten bei Sie, genau wie bei wir.', NULL, 8, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'This is a standard polite opener in a Schreiben Teil 2 e-mail.', 'Das ist ein typischer höflicher Satz in einer E-Mail (Schreiben Teil 2).', 'Polite Requests in a Semi-Formal E-Mail'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ea71c49c-4f5d-5aea-b9c0-c381d07b35d2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f9c05b3c-4ff3-5647-acc2-c01e4e28bb03'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / gern / pünktlich / sein]', 'Write the sentence: I would like to be punctual. (sein → Konjunktiv II, ich; start with Ich)', NULL, 'Ich wäre gern pünktlich.', '["Ich wäre gern pünktlich.","Ich wäre gern pünktlich"]'::jsonb, 'sein becomes wäre for ich; wäre plus an adjective is a common reaction/wish pattern.', 'Aus sein wird wäre bei ich. wäre plus Adjektiv ist ein typisches Muster.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'gern stands right after wäre, before the adjective pünktlich.', 'gern steht direkt nach wäre, vor dem Adjektiv pünktlich.', 'The Four Polite Forms'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f9c05b3c-4ff3-5647-acc2-c01e4e28bb03'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1e306655-d1dc-5be8-b802-c9e463d44a3e'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 5, 'sentence_building', 'Schreib die Frage: [du / am Samstag / im Café / sein]', 'Write the question: Would you be at the café on Saturday? (sein → Konjunktiv II, du; start with the verb)', NULL, 'Wärst du am Samstag im Café?', '["Wärst du am Samstag im Café?","Wärst du am Samstag im Café","Wärest du am Samstag im Café?","Wärest du am Samstag im Café","Wärst du am Samstag im Cafe?","Wärst du am Samstag im Cafe","Wärest du am Samstag im Cafe?","Wärest du am Samstag im Cafe"]'::jsonb, 'sein becomes Wärst for du; the long form Wärest is also correct.', 'Aus sein wird Wärst bei du. Die lange Form Wärest ist auch richtig.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'im Café stands at the end, right before the question mark.', 'im Café steht am Ende, direkt vor dem Fragezeichen.', 'The Four Polite Forms'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1e306655-d1dc-5be8-b802-c9e463d44a3e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4e25f4b1-1412-5164-8ffe-bc33b7c22f5e'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 5, 'sentence_building', 'Schreib die Frage: [ihr / am Samstag / frei / sein]', 'Write the question: Would you (pl.) be free on Saturday? (sein → Konjunktiv II, ihr; start with the verb)', NULL, 'Wärt ihr am Samstag frei?', '["Wärt ihr am Samstag frei?","Wärt ihr am Samstag frei","Wäret ihr am Samstag frei?","Wäret ihr am Samstag frei"]'::jsonb, 'sein becomes Wärt for ihr; the long form Wäret is also correct.', 'Aus sein wird Wärt bei ihr. Die lange Form Wäret ist auch richtig.', NULL, 11, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'frei stands at the end, right before the question mark.', 'frei steht am Ende, direkt vor dem Fragezeichen.', 'Dialogue: Planning the Weekend'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4e25f4b1-1412-5164-8ffe-bc33b7c22f5e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '79ddf253-144a-51ad-b1a0-1fe6ea1bc811'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 5, 'sentence_building', 'Schreib die Frage: [Sie / am Montag / im Büro / sein]', 'Write the formal question: Would you (formal) be in the office on Monday? (sein → Konjunktiv II, Sie; start with the verb)', NULL, 'Wären Sie am Montag im Büro?', '["Wären Sie am Montag im Büro?","Wären Sie am Montag im Büro"]'::jsonb, 'sein becomes Wären for Sie, the same form as wir.', 'Aus sein wird Wären bei Sie, genau wie bei wir.', NULL, 12, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'am Montag stands between the verb and im Büro, describing when.', 'am Montag steht zwischen dem Verb und im Büro und beschreibt, wann.', 'Polite Requests in a Semi-Formal E-Mail'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '79ddf253-144a-51ad-b1a0-1fe6ea1bc811'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '44479b04-025b-54c8-8c9a-e59ce3310c2b'::uuid, 'a49c709b-443b-5978-917d-aaa3e0747d58'::uuid, 5, 'error_correction', 'Finde den Fehler: Wir würde gern kommen.', 'Correct the sentence. wir needs the wir-form of würde, not the ich/er-form. (We would like to come.)', NULL, 'Wir würden gern kommen.', '["Wir würden gern kommen.","Wir würden gern kommen"]'::jsonb, 'wir takes würden, with the ending -n, not würde.', 'wir nimmt würden mit der Endung -n, nicht würde.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'würden gern kommen keeps gern directly before the infinitive kommen.', 'würden gern kommen hat gern direkt vor dem Infinitiv kommen.', 'Common Mistakes with the Polite Forms'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '44479b04-025b-54c8-8c9a-e59ce3310c2b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '820e497e-cdcf-58ac-9586-9e0e308f7527'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 4, 'fill_blank', 'Ich ___ auf den Zug. (warten, ich)', 'Fill in the verb: I am waiting for the train. (verb: warten, ich, + auf + Akkusativ)', NULL, 'warte', '["warte"]'::jsonb, 'warten + auf + Akkusativ is a fixed pair. The ich-form is warte.', 'warten + auf + Akkusativ ist ein festes Paar. ich-Form: warte.', NULL, 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'warte is always followed by auf, never für.', 'Nach warte kommt immer auf, nie für.', 'The Verbs and Their Fixed Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '820e497e-cdcf-58ac-9586-9e0e308f7527'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c8860ad8-0ba4-5061-aad6-e339de7a2030'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 4, 'fill_blank', 'Freut ihr ___ auf die Ferien? (sich freuen, ihr)', 'Fill in the reflexive pronoun: Are you (plural) looking forward to the holidays? (sich freuen + auf, ihr)', NULL, 'euch', '["euch"]'::jsonb, 'sich freuen is reflexive. The ihr-form takes euch.', 'sich freuen ist reflexiv. Bei ihr heißt das Reflexivpronomen euch.', NULL, 2, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'euch follows freut directly, before auf die Ferien.', 'euch steht direkt nach freut, vor auf die Ferien.', 'Reflexive Verbs Already Have a Preposition'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c8860ad8-0ba4-5061-aad6-e339de7a2030'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5db140a4-ef02-5ada-9631-5db27bc9f24f'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 4, 'fill_blank', 'Er freut sich ___ den Brief. (sich freuen, schon passiert)', 'Fill in the preposition: He is happy about the letter. (sich freuen + Akkusativ, something already here)', NULL, 'über', '["über"]'::jsonb, 'sich freuen über + Akkusativ is for something already happening.', 'sich freuen über + Akkusativ: die Freude ist schon da.', NULL, 3, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'The letter is already here, so über, not auf.', 'Der Brief ist schon da, deshalb über, nicht auf.', 'The Verbs and Their Fixed Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5db140a4-ef02-5ada-9631-5db27bc9f24f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'fb044275-a536-5492-ac27-b1650ba73235'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 4, 'fill_blank', 'Interessierst du ___ für Sport? (sich interessieren, du)', 'Fill in the reflexive pronoun: Are you interested in sport? (sich interessieren + für, du)', NULL, 'dich', '["dich"]'::jsonb, 'sich interessieren is reflexive. The du-form takes dich.', 'sich interessieren ist reflexiv. Bei du heißt das Reflexivpronomen dich.', NULL, 4, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'dich follows the verb directly, before für Sport.', 'dich steht direkt nach dem Verb, vor für Sport.', 'Reflexive Verbs Already Have a Preposition'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'fb044275-a536-5492-ac27-b1650ba73235'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'dd3c68e3-e2ef-5ceb-b188-33f0b1d3db35'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 4, 'fill_blank', 'Sie denkt oft ___ ihre Schule. (denken, feste Präposition, nicht über)', 'Fill in the preposition: She often thinks about her school. (denken + the fixed preposition that means ''have in mind'', not über)', NULL, 'an', '["an"]'::jsonb, 'denken always takes an + Akkusativ, not über.', 'denken braucht immer an + Akkusativ, nicht über.', NULL, 5, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'ihre Schule is a thing, but the preposition is still an, not über.', 'ihre Schule ist eine Sache, aber die Präposition ist trotzdem an, nicht über.', 'The Verbs and Their Fixed Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'dd3c68e3-e2ef-5ceb-b188-33f0b1d3db35'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8eff0451-9ff5-5169-970b-abd695c40f6d'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 4, 'multiple_choice', 'Was ist gerade euer Thema? – Wir sprechen ___ die Arbeit.', 'Choose the correct preposition: What''s your topic right now? — We are talking about work. (sprechen + Akkusativ, topic)', '["mit","über","für","von"]'::jsonb, 'über', NULL, 'sprechen über + Akkusativ names the topic. sprechen mit + Dativ names the person.', 'sprechen über + Akkusativ nennt das Thema. sprechen mit + Dativ nennt die Person.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'die Arbeit is the topic, not the person you talk to.', 'die Arbeit ist das Thema, kein Gesprächspartner.', 'The Verbs and Their Fixed Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8eff0451-9ff5-5169-970b-abd695c40f6d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'fd07bfd6-8269-50f1-8a5a-904dca6269bc'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 4, 'fill_blank', 'Ich freue mich schon ___ das Konzert. (sich freuen)', 'Fill in the preposition: I am already looking forward to the concert. (sich freuen + Akkusativ — something still ahead)', NULL, 'auf', '["auf"]'::jsonb, 'sich freuen auf + accusative points to something ahead of you; sich freuen über is about something that is happening now or has happened.', 'sich freuen auf + Akkusativ: für etwas in der Zukunft. Über etwas freust du dich jetzt.', NULL, 7, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'das Konzert is accusative (neuter); the concert is still to come, so auf, not über.', 'das Konzert ist Akkusativ, neutrum. Das Konzert kommt noch.', 'The Verbs and Their Fixed Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'fd07bfd6-8269-50f1-8a5a-904dca6269bc'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c6b07854-7fe4-52d8-ae35-ef8d94408c59'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 4, 'multiple_choice', '___ wartest du gerade?', 'Choose the correct question word for a thing: What are you waiting for right now? (wo(r)- + preposition)', '["Worauf","Woran","Wovon","Womit"]'::jsonb, 'Worauf', NULL, 'warten takes auf. For things, the question word is therefore Worauf.', 'warten braucht auf. Für Sachen fragst du deshalb mit Worauf.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Woran, Wovon and Womit belong to other verbs, not to warten.', 'Woran, Wovon und Womit gehören zu anderen Verben, nicht zu warten.', 'Asking and Answering About Things: wo(r)- and da(r)-'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c6b07854-7fe4-52d8-ae35-ef8d94408c59'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a2e2667d-9423-524f-aa9f-e469838bfbe8'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 4, 'fill_blank', 'Sie träumt oft ___ einer Reise. (träumen, Dativ)', 'Fill in the preposition: She often dreams of a trip. (träumen + Dativ)', NULL, 'von', '["von"]'::jsonb, 'träumen von + Dativ is a fixed pair.', 'träumen von + Dativ ist ein festes Paar.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'einer Reise is Dativ, so von, not für.', 'einer Reise steht im Dativ, deshalb von, nicht für.', 'The Verbs and Their Fixed Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a2e2667d-9423-524f-aa9f-e469838bfbe8'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '9ec096f0-f4bd-5ce0-a85c-60d0db6b8e7d'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 4, 'multiple_choice', 'Woran erinnerst du dich? – Ich erinnere mich ___.', 'Choose the correct da(r)- answer for a thing: What do you remember? — I remember it. (sich erinnern an, replace an + a thing)', '["daran","darauf","davon","dafür"]'::jsonb, 'daran', NULL, 'sich erinnern an + Akkusativ. For things, the answer is daran.', 'sich erinnern an + Akkusativ. Für Sachen antwortest du mit daran.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'an becomes daran, not darauf or davon.', 'an wird zu daran, nicht zu darauf oder davon.', 'Asking and Answering About Things: wo(r)- and da(r)-'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '9ec096f0-f4bd-5ce0-a85c-60d0db6b8e7d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ad5f6d6d-67fa-53ec-82d2-7c3f5d2cb9f6'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 4, 'fill_blank', 'Wir erinnern uns gern ___ den Urlaub. (sich erinnern)', 'Fill in the preposition: We like remembering the holiday. (sich erinnern + Akkusativ)', NULL, 'an', '["an"]'::jsonb, 'sich erinnern an + Akkusativ is a fixed pair.', 'sich erinnern an + Akkusativ ist ein festes Paar.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'den Urlaub is Akkusativ, masculine.', 'den Urlaub ist Akkusativ, maskulin.', 'The Verbs and Their Fixed Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ad5f6d6d-67fa-53ec-82d2-7c3f5d2cb9f6'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd684b4e8-4afa-59db-ae49-008ad6c44747'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 4, 'error_correction', 'Schreib den ganzen Satz richtig: Ich warte für den Bus.', 'Write the whole sentence correctly. warten always takes one fixed preposition, not the English one. (I am waiting for the bus.)', NULL, 'Ich warte auf den Bus.', '["Ich warte auf den Bus.","Ich warte auf den Bus"]'::jsonb, 'warten always takes auf, never für — even though English says ''wait for''.', 'warten braucht immer auf, nicht für.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'auf + Akkusativ is the fixed preposition with warten.', 'auf + Akkusativ ist die feste Präposition bei warten.', 'Common Mistakes with Verbs and Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd684b4e8-4afa-59db-ae49-008ad6c44747'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7660bb1d-1d79-523d-bd46-c529c4f6f6c1'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 4, 'multiple_choice', 'Ich habe Angst ___.', 'Choose the correct preposition + case: I am afraid of the exam. (Angst haben vor + Dativ)', '["vor der Prüfung","auf die Prüfung","für die Prüfung","über die Prüfung"]'::jsonb, 'vor der Prüfung', NULL, 'Angst haben vor + Dativ is a fixed pair.', 'Angst haben vor + Dativ ist ein festes Paar.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'vor takes the Dativ here: der Prüfung.', 'vor braucht hier den Dativ: der Prüfung.', 'The Verbs and Their Fixed Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7660bb1d-1d79-523d-bd46-c529c4f6f6c1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '98a47d55-7ce5-53f0-a8d2-aba8d31d057c'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / Angst haben / vor / die Prüfung]', 'Write the sentence: I am afraid of the exam. (Angst haben vor + Dativ, ich; start with Ich)', NULL, 'Ich habe Angst vor der Prüfung.', '["Ich habe Angst vor der Prüfung.","Ich habe Angst vor der Prüfung","Ich habe vor der Prüfung Angst.","Ich habe vor der Prüfung Angst"]'::jsonb, 'Angst haben vor + Dativ: die Prüfung becomes der Prüfung in the Dativ. Angst is a noun that can also move away from the verb: Ich habe vor der Prüfung Angst. is equally correct.', 'Angst haben vor + Dativ: vor der Prüfung.', NULL, 1, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'In the Dativ it is der Prüfung, not die Prüfung.', 'Im Dativ heißt es der Prüfung, nicht die Prüfung.', 'The Verbs and Their Fixed Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '98a47d55-7ce5-53f0-a8d2-aba8d31d057c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '78945102-55be-58ad-9466-4d38fa627ade'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [sie / sich kümmern / um / die Kinder]', 'Write the sentence: She takes care of the children. (sich kümmern um + Akkusativ, sie singular; start with Sie)', NULL, 'Sie kümmert sich um die Kinder.', '["Sie kümmert sich um die Kinder.","Sie kümmert sich um die Kinder"]'::jsonb, 'sich kümmern um + Akkusativ. die Kinder stays the same in the Akkusativ plural.', 'sich kümmern um + Akkusativ. die Kinder bleibt im Akkusativ Plural gleich.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sich follows kümmert directly, then um die Kinder.', 'sich steht direkt nach kümmert, dann um die Kinder.', 'Reflexive Verbs Already Have a Preposition'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '78945102-55be-58ad-9466-4d38fa627ade'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5fa28c02-f0a6-51cd-bacb-92a95aefce94'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / anfangen / mit / die Arbeit]', 'Write the sentence: We are starting the work. (anfangen mit + Dativ, wir; start with Wir)', NULL, 'Wir fangen mit der Arbeit an.', '["Wir fangen mit der Arbeit an.","Wir fangen mit der Arbeit an"]'::jsonb, 'anfangen is separable. mit der Arbeit sits in the middle, an at the end.', 'anfangen ist trennbar. mit der Arbeit steht in der Mitte, an am Ende.', NULL, 3, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'In the Dativ it is der Arbeit.', 'Im Dativ heißt es der Arbeit.', 'The Verbs and Their Fixed Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5fa28c02-f0a6-51cd-bacb-92a95aefce94'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'aa24f046-e454-5081-8b4e-8efff3a9d27b'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / sich bedanken / für / die Hilfe]', 'Write the sentence: I thank you for the help. (sich bedanken für + Akkusativ, ich; start with Ich)', NULL, 'Ich bedanke mich für die Hilfe.', '["Ich bedanke mich für die Hilfe.","Ich bedanke mich für die Hilfe"]'::jsonb, 'sich bedanken für + Akkusativ. die Hilfe stays the same in the Akkusativ.', 'sich bedanken für + Akkusativ. die Hilfe bleibt im Akkusativ gleich.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'mich follows bedanke directly.', 'mich steht direkt nach bedanke.', 'Reflexive Verbs Already Have a Preposition'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'aa24f046-e454-5081-8b4e-8efff3a9d27b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8227d3c6-4654-536b-8dba-709ee514279f'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [er / fragen / nach / der Weg]', 'Write the sentence: He is asking for directions. (fragen nach + Dativ, er; start with Er)', NULL, 'Er fragt nach dem Weg.', '["Er fragt nach dem Weg.","Er fragt nach dem Weg"]'::jsonb, 'fragen nach + Dativ. der Weg becomes dem Weg in the Dativ.', 'fragen nach + Dativ. der Weg wird im Dativ zu dem Weg.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'In the Dativ it is dem Weg.', 'Im Dativ heißt es dem Weg.', 'The Verbs and Their Fixed Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8227d3c6-4654-536b-8dba-709ee514279f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ef14caee-ee32-50cb-8d87-36f349a2872c'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / telefonieren / mit / mein Bruder]', 'Write the sentence: I am calling my brother. (telefonieren mit + Dativ, ich; start with Ich)', NULL, 'Ich telefoniere mit meinem Bruder.', '["Ich telefoniere mit meinem Bruder.","Ich telefoniere mit meinem Bruder"]'::jsonb, 'telefonieren mit + Dativ. mein Bruder becomes meinem Bruder in the Dativ.', 'telefonieren mit + Dativ. mein Bruder wird im Dativ zu meinem Bruder.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'mit takes the Dativ, so meinem Bruder.', 'mit braucht den Dativ, deshalb meinem Bruder.', 'The Verbs and Their Fixed Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ef14caee-ee32-50cb-8d87-36f349a2872c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '79c0de85-6daf-5786-91d6-ea1ba84bd7d3'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / sich anmelden / für / der Deutschkurs]', 'Write the sentence: I am registering for the German course. (sich anmelden für + Akkusativ, ich; start with Ich)', NULL, 'Ich melde mich für den Deutschkurs an.', '["Ich melde mich für den Deutschkurs an.","Ich melde mich für den Deutschkurs an"]'::jsonb, 'sich anmelden is separable: melde ... an. für den Deutschkurs sits in the middle.', 'sich anmelden ist trennbar: melde ... an. für den Deutschkurs steht in der Mitte.', NULL, 7, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'In the Akkusativ it is den Deutschkurs.', 'Im Akkusativ heißt es den Deutschkurs.', 'Reflexive Verbs Already Have a Preposition'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '79c0de85-6daf-5786-91d6-ea1ba84bd7d3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'de1d6ae7-90ce-5a88-94f0-8a8cc9f77244'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 5, 'sentence_building', 'Schreib die Frage: [du / warten / auf / ? (Sache)]', 'Write the wo(r)- question for a thing: What are you waiting for? (warten auf, du; start with the question word)', NULL, 'Worauf wartest du?', '["Worauf wartest du?","Worauf wartest du"]'::jsonb, 'For things, ask with wo(r)- + preposition: Worauf wartest du?', 'Für Sachen fragst du mit wo(r)- + Präposition: Worauf wartest du?', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'auf starts with a vowel, so Worauf takes the r.', 'auf beginnt mit einem Vokal, deshalb Worauf mit r.', 'Asking and Answering About Things: wo(r)- and da(r)-'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'de1d6ae7-90ce-5a88-94f0-8a8cc9f77244'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1bbe29f5-595d-5e56-b316-f582d80b1564'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 5, 'sentence_building', 'Schreib die Antwort: [ich / sich freuen / auf / das Wochenende] (antworte mit da(r)-)', 'Write the answer with a da(r)- form: I am looking forward to it. (sich freuen auf + das Wochenende, ich; answer with da(r)-, not auf es)', NULL, 'Ich freue mich darauf.', '["Ich freue mich darauf.","Ich freue mich darauf","Darauf freue ich mich.","Darauf freue ich mich"]'::jsonb, 'For things, answer with da(r)- + preposition: darauf, never auf es.', 'Für Sachen antwortest du mit da(r)- + Präposition: darauf, nicht auf es.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'mich follows freue directly, darauf at the end.', 'mich steht direkt nach freue. darauf steht am Ende oder am Anfang.', 'Asking and Answering About Things: wo(r)- and da(r)-'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1bbe29f5-595d-5e56-b316-f582d80b1564'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1e8f15da-3820-5ef0-97e0-9a35ccd93fc3'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 5, 'sentence_building', 'Schreib die Frage: [du / denken / an / wen (Person)]', 'Write the question for a person: Who are you thinking of? (denken an, du; use an wen, not woran)', NULL, 'An wen denkst du?', '["An wen denkst du?","An wen denkst du"]'::jsonb, 'For a person, ask with preposition + wen, not woran.', 'Bei einer Person fragst du mit Präposition + wen, nicht mit woran.', NULL, 10, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'an stays before wen, just as with a thing.', 'an bleibt vor wen stehen, genau wie bei einer Sache.', 'Things or People? Two Ways to Ask and Answer'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1e8f15da-3820-5ef0-97e0-9a35ccd93fc3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a696d1a3-f115-5112-ac05-0820e62b8ddf'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 5, 'error_correction', 'Schreib den ganzen Satz richtig: Ich telefoniere von meiner Schwester.', 'Write the whole sentence correctly. telefonieren has one fixed preposition, not von. (I am calling my sister.)', NULL, 'Ich telefoniere mit meiner Schwester.', '["Ich telefoniere mit meiner Schwester.","Ich telefoniere mit meiner Schwester"]'::jsonb, 'telefonieren always takes mit + Dativ, never von.', 'telefonieren braucht immer mit + Dativ, nicht von.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'meiner Schwester is Dativ after mit.', 'meiner Schwester steht im Dativ nach mit.', 'Common Mistakes with Verbs and Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a696d1a3-f115-5112-ac05-0820e62b8ddf'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4a66b4f9-9424-5df0-87df-76b7ad4e7435'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 5, 'sentence_building', 'Schreib die Frage: [du / sprechen / mit / deine Chefin]', 'Write the yes/no question: Are you talking to your boss? (sprechen mit + Dativ, du; start with the verb)', NULL, 'Sprichst du mit deiner Chefin?', '["Sprichst du mit deiner Chefin?","Sprichst du mit deiner Chefin"]'::jsonb, 'sprechen has a vowel change: du sprichst. mit + Dativ: deiner Chefin.', 'sprechen ist ein Verb mit Vokalwechsel: du sprichst. mit + Dativ: deiner Chefin.', NULL, 12, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'In a yes/no question the verb opens the sentence: Sprichst du …?', 'In der Ja/Nein-Frage steht das Verb zuerst: Sprichst du …?', 'The Verbs and Their Fixed Prepositions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4a66b4f9-9424-5df0-87df-76b7ad4e7435'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '24382117-0914-50eb-aa5c-8a48cec67868'::uuid, 'af8ae4c1-9b8d-5317-8a53-b2e02cc90dcc'::uuid, 5, 'sentence_building', 'Schreib die Frage: [Sie / sich interessieren / für / die Kurse]', 'Write the formal question: Are you interested in the courses? (sich interessieren für + Akkusativ, Sie; start with the verb)', NULL, 'Interessieren Sie sich für die Kurse?', '["Interessieren Sie sich für die Kurse?","Interessieren Sie sich für die Kurse"]'::jsonb, 'sich interessieren is reflexive. The Sie-form still takes sich.', 'sich interessieren ist reflexiv. Bei Sie bleibt das Reflexivpronomen sich.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'In the question, the verb opens the sentence: Interessieren Sie sich …?', 'In der Frage steht das Verb zuerst: Interessieren Sie sich …?', 'Reflexive Verbs Already Have a Preposition'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '24382117-0914-50eb-aa5c-8a48cec67868'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a9efb6a7-b088-5aaa-8d97-01ee3aa0e257'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 4, 'fill_blank', 'Wissen Sie, ___ die Bank heute geöffnet hat? (Direkte Frage: Hat die Bank heute geöffnet?)', 'Fill in the connector for a yes/no question turned indirect: Do you know whether the bank is open today? (Direct question: Hat die Bank heute geöffnet?)', NULL, 'ob', '["ob"]'::jsonb, 'A yes/no question has no question word, so it becomes ob + verb-final.', 'Eine Ja/Nein-Frage hat kein Fragewort. Sie wird zu ob + Verb am Ende.', NULL, 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'There is no W-word in Hat die Bank heute geöffnet?, so ob is the only possible connector.', 'In Hat die Bank heute geöffnet? gibt es kein W-Wort. Deshalb ist ob der einzig mögliche Konnektor.', 'From Direct Question to Indirect Question'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a9efb6a7-b088-5aaa-8d97-01ee3aa0e257'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8c44e29a-e600-5363-be27-e4ddee42cccd'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 4, 'fill_blank', 'Können Sie mir sagen, ___ der Fahrkartenautomat ist? (Direkte Frage: Wo ist der Fahrkartenautomat?)', 'Fill in the connector: Can you tell me where the ticket machine is? (Direct question: Wo ist der Fahrkartenautomat?)', NULL, 'wo', '["wo"]'::jsonb, 'The direct question already has the W-word wo — it stays the same in the indirect question.', 'Die direkte Frage hat schon das W-Wort wo. Es bleibt in der indirekten Frage gleich.', NULL, 2, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'wo is kept unchanged; only the verb ist moves to the end.', 'wo bleibt gleich. Nur das Verb ist wandert ans Ende.', 'From Direct Question to Indirect Question'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8c44e29a-e600-5363-be27-e4ddee42cccd'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bf633971-4590-52dc-b2c3-39a470beac95'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 4, 'fill_blank', 'Weißt du, ___ die Praxis geöffnet hat? (Direkte Frage: Wann hat die Praxis geöffnet?)', 'Fill in the connector: Do you know when the practice is open? (Direct question: Wann hat die Praxis geöffnet?)', NULL, 'wann', '["wann"]'::jsonb, 'The W-word wann carries over unchanged from the direct question.', 'Das W-Wort wann bleibt aus der direkten Frage unverändert.', NULL, 3, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'wann is the connector; hat closes the clause at the end.', 'wann ist der Konnektor. hat steht ganz am Ende.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bf633971-4590-52dc-b2c3-39a470beac95'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ccda9255-ce99-5832-b02e-4d37404125c8'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 4, 'fill_blank', 'Ich weiß nicht, ___ heute im Büro ist. (Direkte Frage: Wer ist heute im Büro?)', 'Fill in the connector: I don''t know who is in the office today. (Direct question: Wer ist heute im Büro?)', NULL, 'wer', '["wer"]'::jsonb, 'wer is both the connector and the subject of the clause.', 'wer ist gleichzeitig Konnektor und Subjekt im Nebensatz.', NULL, 4, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'wer heute im Büro ist keeps heute before the final verb ist.', 'wer heute im Büro ist: heute steht vor dem Verb ist.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ccda9255-ce99-5832-b02e-4d37404125c8'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c7515d22-5e45-50c4-9b02-12119c5584b2'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 4, 'fill_blank', 'Ich möchte wissen, ___ die Suppe kostet. (Direkte Frage: Was kostet die Suppe?)', 'Fill in the connector: I would like to know what the soup costs. (Direct question: Was kostet die Suppe?)', NULL, 'was', '["was"]'::jsonb, 'was stays the same word; the verb kostet moves to the end.', 'was bleibt gleich. Das Verb kostet wandert ans Ende.', NULL, 5, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'The statement frame Ich möchte wissen takes a period, not a question mark.', 'Der Aussage-Rahmen Ich möchte wissen endet mit einem Punkt, nicht mit einem Fragezeichen.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c7515d22-5e45-50c4-9b02-12119c5584b2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b04d3705-1b7d-5d0e-8c47-63d2c0489814'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 4, 'fill_blank', 'Ich frage mich, ___ der Bus nicht kommt. (Direkte Frage: Warum kommt der Bus nicht?)', 'Fill in the connector: I wonder why the bus isn''t coming. (Direct question: Warum kommt der Bus nicht?)', NULL, 'warum', '["warum"]'::jsonb, 'warum carries over unchanged; nicht stays before the final verb kommt.', 'warum bleibt unverändert. nicht steht vor dem Verb kommt.', NULL, 6, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'warum is the only W-word that fits the meaning ''why''.', 'warum ist das einzige W-Wort mit der Bedeutung ''warum, weshalb''.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b04d3705-1b7d-5d0e-8c47-63d2c0489814'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2cd94392-b4d7-59c9-bf44-23a565bbae6e'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 4, 'fill_blank', 'Können Sie mir sagen, wie viel das Ticket ___? (kosten, Präsens, es)', 'Fill in the verb at the end: Can you tell me how much the ticket costs? (verb: kosten, present, es)', NULL, 'kostet', '["kostet"]'::jsonb, 'The connector wie viel stays at the front; the finite verb kostet moves to the very end.', 'wie viel bleibt vorn. Das Verb kostet wandert ganz ans Ende.', NULL, 7, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'das Ticket is the subject, so the verb takes the es/sie-form: kostet.', 'das Ticket ist das Subjekt, deshalb steht das Verb in der es-Form: kostet.', 'How to Build an Indirect Question'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2cd94392-b4d7-59c9-bf44-23a565bbae6e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3724496a-7726-57e5-8de7-48f1f4f9d3f9'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 4, 'fill_blank', 'Weißt du, ob ich das Formular heute ___? (abgeben, müssen, Präsens, ich)', 'Fill in the verb-final cluster: Do you know whether I have to hand in the form today? (abgeben + müssen, present, ich)', NULL, 'abgeben muss', '["abgeben muss"]'::jsonb, 'With a modal verb, the infinitive comes first and the modal closes the clause: abgeben muss.', 'Bei einem Modalverb steht der Infinitiv zuerst, das Modalverb ganz am Ende: abgeben muss.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The separable verb abgeben stays whole as an infinitive right before the modal muss.', 'Das trennbare Verb abgeben bleibt als ein ganzer Infinitiv direkt vor dem Modalverb muss.', 'Verb-Final: What You Already Know'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3724496a-7726-57e5-8de7-48f1f4f9d3f9'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a8f69482-fbdd-5449-a659-0d2dd70e5343'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 4, 'error_correction', 'Finde den Fehler: Ich weiß nicht, ob kommt der Zug pünktlich.', 'Correct the word order. The verb must stand at the very end of the ob-clause. (I don''t know whether the train is coming on time.)', NULL, 'Ich weiß nicht, ob der Zug pünktlich kommt.', '["Ich weiß nicht, ob der Zug pünktlich kommt.","Ich weiß nicht, ob der Zug pünktlich kommt"]'::jsonb, 'kommt belongs at the end of the ob-clause, not directly after ob.', 'kommt gehört ganz ans Ende, nicht direkt nach ob.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ob sends the whole clause into verb-final order, exactly like dass or weil.', 'ob schickt den ganzen Nebensatz in die Verbendstellung, genau wie dass oder weil.', 'How to Build an Indirect Question'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a8f69482-fbdd-5449-a659-0d2dd70e5343'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ab59c0bd-21e7-5f45-bf61-e8ea594b412a'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence is correct for: Do you know where the train station is? (question frame)', '["Wissen Sie, wo der Bahnhof ist.","Wissen Sie, wo der Bahnhof ist?","Wissen Sie wo der Bahnhof ist?","Wissen Sie, wo ist der Bahnhof?"]'::jsonb, 'Wissen Sie, wo der Bahnhof ist?', NULL, 'Wissen Sie …? is a question frame, so the sentence ends in a question mark; the comma before wo and the verb-final order are both required.', 'Wissen Sie …? ist ein Frage-Rahmen, deshalb endet der Satz mit einem Fragezeichen. Komma und Verb am Ende sind auch nötig.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The other options miss the question mark, miss the comma, or leave the verb in second position.', 'Die anderen Sätze haben kein Fragezeichen, kein Komma oder das Verb nicht am Ende.', 'Frames and the Question Mark Rule'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ab59c0bd-21e7-5f45-bf61-e8ea594b412a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '45d131ad-330d-55b1-861c-104202f23a3d'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence is correct for: I don''t know when the course starts. (statement frame)', '["Ich weiß nicht, wann der Kurs beginnt?","Ich weiß nicht, wann der Kurs beginnt.","Ich weiß nicht wann der Kurs beginnt.","Ich weiß nicht, wann beginnt der Kurs."]'::jsonb, 'Ich weiß nicht, wann der Kurs beginnt.', NULL, 'Ich weiß nicht is a statement frame, so it ends in a period; the comma and verb-final order are both required.', 'Ich weiß nicht ist ein Aussage-Rahmen, deshalb endet der Satz mit einem Punkt. Komma und Verb am Ende sind nötig.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The other options use a question mark, drop the comma, or leave the verb in second position.', 'Die anderen Sätze haben ein Fragezeichen, kein Komma oder das Verb nicht am Ende.', 'Frames and the Question Mark Rule'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '45d131ad-330d-55b1-861c-104202f23a3d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bb5ad0b3-d921-5999-995f-44697ffca9ad'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 4, 'multiple_choice', 'Wie sagt man das indirekt? Direkte Frage: Wer arbeitet heute?', 'Turn the direct question into an indirect one after Ich weiß nicht, …: Who is working today?', '["Ich weiß nicht, wer heute arbeitet.","Ich weiß nicht, wer arbeitet heute.","Ich weiß nicht, ob wer heute arbeitet.","Ich weiß nicht, heute wer arbeitet."]'::jsonb, 'Ich weiß nicht, wer heute arbeitet.', NULL, 'wer stays as the connector and subject; heute moves inside the clause, before the final verb arbeitet.', 'wer bleibt Konnektor und Subjekt. heute steht im Nebensatz vor dem Verb arbeitet.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The other options put heute after the verb, add an unnecessary ob, or misplace wer.', 'Die anderen Sätze stellen heute hinter das Verb. Oder sie fügen ein unnötiges ob hinzu.', 'From Direct Question to Indirect Question'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bb5ad0b3-d921-5999-995f-44697ffca9ad'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '607c76d0-1406-5ea8-83d4-59f078ae5cf5'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 4, 'fill_blank', 'Können Sie mir sagen, ___ ich zur Apotheke komme? (Direkte Frage: Wie komme ich zur Apotheke?)', 'Fill in the connector: Can you tell me how to get to the pharmacy? (Direct question: Wie komme ich zur Apotheke?)', NULL, 'wie', '["wie"]'::jsonb, 'wie asks about manner and stays the same word; the verb komme moves to the end.', 'wie fragt nach der Art und Weise und bleibt gleich. Das Verb komme steht am Ende.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The direct question Wie komme ich zur Apotheke? already has the W-word wie, so it carries over unchanged.', 'Die direkte Frage Wie komme ich zur Apotheke? hat schon das W-Wort wie. Es bleibt gleich.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '607c76d0-1406-5ea8-83d4-59f078ae5cf5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'daa168d9-66fa-5f26-843e-05d6f3ca3ad5'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / wissen / nicht / wie / das / heißen]', 'Write the sentence: I don''t know what that is called — in German you ask "wie heißt das". (frame: Ich weiß nicht; W-word wie; start with Ich)', NULL, 'Ich weiß nicht, wie das heißt.', '["Ich weiß nicht, wie das heißt.","Ich weiß nicht, wie das heißt"]'::jsonb, 'wie asks here how something is named; the verb heißt closes the clause.', 'wie fragt hier danach, wie etwas heißt. Das Verb heißt steht am Ende.', NULL, 1, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Ich weiß nicht is a statement frame, so the sentence ends in a period.', 'Ich weiß nicht ist ein Aussage-Rahmen, der Satz endet mit einem Punkt.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'daa168d9-66fa-5f26-843e-05d6f3ca3ad5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e00431b8-0309-5a8e-9eae-1b4f75833e84'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 5, 'sentence_building', 'Schreib die Frage: [du / mir / sagen / können / wo / die Toilette sein]', 'Write the question: Can you tell me where the restroom is? (frame: Kannst du mir sagen; start with Kannst)', NULL, 'Kannst du mir sagen, wo die Toilette ist?', '["Kannst du mir sagen, wo die Toilette ist?","Kannst du mir sagen, wo die Toilette ist"]'::jsonb, 'können opens the question in the du-form; wo introduces the indirect question with ist at the end.', 'können eröffnet die Frage in der du-Form. wo leitet die indirekte Frage ein, ist steht am Ende.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Kannst du mir sagen is the informal counterpart to Können Sie mir sagen.', 'Kannst du mir sagen ist die informelle Variante von Können Sie mir sagen.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e00431b8-0309-5a8e-9eae-1b4f75833e84'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd4c8398e-515c-5181-9e9e-e31091b84db7'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / wissen / möchten / wann / der Kurs / beginnen]', 'Write the sentence: I would like to know when the course starts. (frame: Ich möchte wissen; start with Ich)', NULL, 'Ich möchte wissen, wann der Kurs beginnt.', '["Ich möchte wissen, wann der Kurs beginnt.","Ich möchte wissen, wann der Kurs beginnt"]'::jsonb, 'Ich möchte wissen is a statement frame, so the sentence ends in a period; beginnt closes the clause.', 'Ich möchte wissen ist ein Aussage-Rahmen, der Satz endet mit einem Punkt. beginnt steht am Ende.', NULL, 3, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'wann stays fixed at the front of the embedded clause; only the verb moves.', 'wann bleibt fest vorn im Nebensatz. Nur das Verb bewegt sich.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd4c8398e-515c-5181-9e9e-e31091b84db7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '77fd8930-2b8a-5e8f-822e-cf074090fbb3'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 5, 'sentence_building', 'Schreib die Frage: [Sie / mir / sagen / können / was / ich / am Schalter / zeigen müssen]', 'Write the question: Can you tell me what I need to show at the counter? (frame: Können Sie mir sagen; start with Können)', NULL, 'Können Sie mir sagen, was ich am Schalter zeigen muss?', '["Können Sie mir sagen, was ich am Schalter zeigen muss?","Können Sie mir sagen, was ich am Schalter zeigen muss"]'::jsonb, 'was is both connector and object; the infinitive zeigen comes before the modal muss at the end.', 'was ist Konnektor und Objekt zugleich. Der Infinitiv zeigen steht vor dem Modalverb muss am Ende.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Können Sie mir sagen is a question frame, so the sentence ends with a question mark.', 'Können Sie mir sagen ist ein Frage-Rahmen, deshalb endet der Satz mit einem Fragezeichen.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '77fd8930-2b8a-5e8f-822e-cf074090fbb3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '42bd1125-daa2-582f-b47b-94ff75f3c437'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 5, 'sentence_building', 'Schreib die Frage: [du / wissen / wer / heute / im Büro sein]', 'Write the question: Do you know who is in the office today? (frame: Weißt du; start with Weißt)', NULL, 'Weißt du, wer heute im Büro ist?', '["Weißt du, wer heute im Büro ist?","Weißt du, wer heute im Büro ist"]'::jsonb, 'wer is the subject and connector; heute stands before the final verb ist.', 'wer ist Subjekt und Konnektor. heute steht vor dem Verb ist.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Weißt du is a question frame, so a question mark closes the sentence.', 'Weißt du ist ein Frage-Rahmen, deshalb steht am Ende ein Fragezeichen.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '42bd1125-daa2-582f-b47b-94ff75f3c437'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0ce16794-f157-5199-8395-4aed15c3c679'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 5, 'sentence_building', 'Schreib die Frage: [du / wissen / warum / der Kurs / heute / nicht stattfinden]', 'Write the question: Do you know why the course isn''t taking place today? (frame: Weißt du; start with Weißt)', NULL, 'Weißt du, warum der Kurs heute nicht stattfindet?', '["Weißt du, warum der Kurs heute nicht stattfindet?","Weißt du, warum der Kurs heute nicht stattfindet"]'::jsonb, 'The separable verb stattfinden rejoins as one word at the end of the clause.', 'Das trennbare Verb stattfinden bleibt am Ende zusammen.', NULL, 6, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Weißt du is a question frame, so the sentence ends with a question mark.', 'Weißt du ist ein Frage-Rahmen, deshalb endet der Satz mit einem Fragezeichen.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0ce16794-f157-5199-8395-4aed15c3c679'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd424778b-7684-5530-aa9d-b5b65fe1e747'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / möchten / wissen / wie viel / das Zimmer / kosten]', 'Write the sentence: I would like to know how much the room costs. (frame: Ich möchte wissen; start with Ich)', NULL, 'Ich möchte wissen, wie viel das Zimmer kostet.', '["Ich möchte wissen, wie viel das Zimmer kostet.","Ich möchte wissen, wie viel das Zimmer kostet"]'::jsonb, 'wie viel stays together at the front; the verb kostet closes the clause.', 'wie viel bleibt zusammen vorn. Das Verb kostet steht am Ende.', NULL, 7, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Ich möchte wissen is a statement frame, so the sentence ends in a period.', 'Ich möchte wissen ist ein Aussage-Rahmen, der Satz endet mit einem Punkt.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd424778b-7684-5530-aa9d-b5b65fe1e747'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '93bc046a-52d0-50b0-8e5a-5f8f533fc499'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / keine Ahnung / haben / wie lange / die Prüfung / dauern]', 'Write the sentence: I have no idea how long the exam lasts. (frame: Ich habe keine Ahnung; start with Ich)', NULL, 'Ich habe keine Ahnung, wie lange die Prüfung dauert.', '["Ich habe keine Ahnung, wie lange die Prüfung dauert.","Ich habe keine Ahnung, wie lange die Prüfung dauert"]'::jsonb, 'wie lange stays together; the subject die Prüfung comes before the final verb dauert.', 'wie lange bleibt zusammen. Das Subjekt die Prüfung steht vor dem Verb dauert.', NULL, 8, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Ich habe keine Ahnung is a frozen statement frame, so the sentence ends in a period.', 'Ich habe keine Ahnung ist ein fester Aussage-Rahmen, der Satz endet mit einem Punkt.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '93bc046a-52d0-50b0-8e5a-5f8f533fc499'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3804ea80-0bdc-578a-a4b1-148605a01220'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 5, 'sentence_building', 'Schreib die Frage: [Sie / mir / sagen / können / welches / Ticket / ich / kaufen sollen]', 'Write the question: Can you tell me which ticket I should buy? (frame: Können Sie mir sagen; start with Können)', NULL, 'Können Sie mir sagen, welches Ticket ich kaufen soll?', '["Können Sie mir sagen, welches Ticket ich kaufen soll?","Können Sie mir sagen, welches Ticket ich kaufen soll"]'::jsonb, 'welches Ticket opens the clause as one unit; the infinitive kaufen comes before the modal soll at the end.', 'welches Ticket eröffnet den Nebensatz als Einheit. Der Infinitiv kaufen steht vor dem Modalverb soll am Ende.', NULL, 9, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Können Sie mir sagen is a question frame, so the sentence ends with a question mark.', 'Können Sie mir sagen ist ein Frage-Rahmen, deshalb endet der Satz mit einem Fragezeichen.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3804ea80-0bdc-578a-a4b1-148605a01220'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '60058f5a-32a5-56c2-876f-1ee680327855'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / keine Ahnung / haben / mit wem / ich / telefonieren sollen]', 'Write the sentence: I have no idea who I should call. (frame: Ich habe keine Ahnung; start with Ich)', NULL, 'Ich habe keine Ahnung, mit wem ich telefonieren soll.', '["Ich habe keine Ahnung, mit wem ich telefonieren soll.","Ich habe keine Ahnung, mit wem ich telefonieren soll"]'::jsonb, 'mit wem stays together at the front; the infinitive telefonieren comes before the modal soll at the end.', 'mit wem bleibt zusammen vorn. Der Infinitiv telefonieren steht vor dem Modalverb soll am Ende.', NULL, 10, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'For a person after a fixed preposition German uses mit wem, not a wo(r)-compound.', 'Bei einer Person nach einer festen Präposition sagt man mit wem, kein wo(r)-Wort.', 'The W-Words in Indirect Questions'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '60058f5a-32a5-56c2-876f-1ee680327855'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0b980292-8171-5000-8784-98d163d7e619'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 5, 'error_correction', 'Finde den Fehler: Ich weiß nicht wie viel die Miete kostet.', 'Correct the punctuation. A comma always comes before an indirect question. (I don''t know how much the rent costs.)', NULL, 'Ich weiß nicht, wie viel die Miete kostet.', '["Ich weiß nicht, wie viel die Miete kostet.","Ich weiß nicht, wie viel die Miete kostet"]'::jsonb, 'A comma always separates the frame from the indirect question, exactly like before any other Nebensatz.', 'Ein Komma trennt immer den Rahmen von der indirekten Frage, genau wie vor jedem anderen Nebensatz.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only the comma was missing; the verb-final order was already correct.', 'Nur das Komma hat gefehlt. Die Verbendstellung war schon richtig.', 'Frames and the Question Mark Rule'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0b980292-8171-5000-8784-98d163d7e619'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a5b6ad5c-cb68-5bcd-884c-6ad30502c15a'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 5, 'error_correction', 'Finde den Fehler: Ich weiß nicht, wo der Ausgang ist?', 'Correct the punctuation. Ich weiß nicht is a statement frame, so the sentence ends in a period. (I don''t know where the exit is.)', NULL, 'Ich weiß nicht, wo der Ausgang ist.', '["Ich weiß nicht, wo der Ausgang ist.","Ich weiß nicht, wo der Ausgang ist"]'::jsonb, 'The frame Ich weiß nicht is a statement, not a question, so it must end with a period.', 'Der Rahmen Ich weiß nicht ist eine Aussage, keine Frage, deshalb endet er mit einem Punkt.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only the final punctuation mark was wrong; wo der Ausgang ist was already correct.', 'Nur das Satzzeichen am Ende war falsch. wo der Ausgang ist war schon richtig.', 'Frames and the Question Mark Rule'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a5b6ad5c-cb68-5bcd-884c-6ad30502c15a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a8654724-6497-54c8-8b74-71d237648aae'::uuid, '316c318e-cfa2-5a57-b690-891e137d4180'::uuid, 5, 'multiple_choice', 'Du stehst am Schalter und kennst den Zug nicht. Was fragst du höflich?', 'You''re at the ticket counter and don''t know the train. What do you ask politely?', '["Wissen Sie, wann der nächste Zug fährt?","Sie wissen, wann der nächste Zug fährt?","Wissen Sie wann fährt der nächste Zug?","Wissen Sie, wann fährt der nächste Zug?"]'::jsonb, 'Wissen Sie, wann der nächste Zug fährt?', NULL, 'Wissen Sie opens the question, a comma follows, and fährt moves to the end of the embedded clause.', 'Wissen Sie eröffnet die Frage, danach folgt ein Komma, und fährt wandert ganz ans Ende.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The other options miss the inversion of Wissen Sie, drop the comma, or leave the verb in second position.', 'Die anderen Sätze haben keine Inversion. Oder das Komma fehlt. Oder das Verb steht nicht am Ende.', 'Frames and the Question Mark Rule'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a8654724-6497-54c8-8b74-71d237648aae'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '59569d77-7f51-5c74-a341-37360ffce4eb'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 4, 'fill_blank', 'Ich habe Lust, heute Abend ___. (tanzen)', 'Fill in the zu-infinitive: I feel like dancing tonight. (verb: tanzen)', NULL, 'zu tanzen', '["zu tanzen"]'::jsonb, 'After Lust haben add a comma, then zu + infinitive: zu tanzen.', 'Nach Lust haben kommt ein Komma, dann zu + Infinitiv: zu tanzen.', NULL, 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'tanzen is not separable, so zu simply goes in front of it.', 'tanzen ist nicht trennbar, deshalb steht zu einfach davor.', 'Verbs and Expressions Before zu + Infinitive'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '59569d77-7f51-5c74-a341-37360ffce4eb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2052c54d-8ca1-59a0-a2dd-3e7f2497c882'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 4, 'fill_blank', 'Wir haben keine Zeit, heute ___. (kochen)', 'Fill in the zu-infinitive: We have no time to cook today. (verb: kochen)', NULL, 'zu kochen', '["zu kochen"]'::jsonb, 'keine Zeit haben takes the same pattern: comma, then zu + infinitive.', 'keine Zeit haben nimmt dasselbe Muster: Komma, dann zu + Infinitiv.', NULL, 2, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'kochen is not separable, so zu stands directly before it.', 'kochen ist nicht trennbar, zu steht direkt davor.', 'Verbs and Expressions Before zu + Infinitive'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2052c54d-8ca1-59a0-a2dd-3e7f2497c882'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '76cac2bb-98e6-5e98-a15e-0a133fff5e6e'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 4, 'fill_blank', 'Ich habe vergessen, den Termin ___. (absagen)', 'Fill in the separable verb with zu: I forgot to cancel the appointment. (verb: absagen — separable, zu goes inside)', NULL, 'abzusagen', '["abzusagen"]'::jsonb, 'absagen is separable: zu slots between ab- and -sagen, written as one word: abzusagen.', 'absagen ist trennbar: zu kommt zwischen ab- und -sagen: abzusagen.', NULL, 3, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Compare anrufen -> anzurufen: same pattern, different prefix.', 'Vergleiche anrufen -> anzurufen: gleiches Muster, anderes Präfix.', 'Separable Verbs with zu: an-zu-rufen'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '76cac2bb-98e6-5e98-a15e-0a133fff5e6e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8f88ee61-1fb6-5423-abf3-1454eb93354b'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 4, 'fill_blank', 'Ich habe vor, morgen ___. (einkaufen)', 'Fill in the separable verb with zu: I''m planning to go shopping tomorrow. (verb: einkaufen — separable)', NULL, 'einzukaufen', '["einzukaufen"]'::jsonb, 'einkaufen is separable: zu slots between ein- and -kaufen, written as one word: einzukaufen.', 'einkaufen ist trennbar: zu kommt zwischen ein- und -kaufen: einzukaufen.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'vorhaben (ich habe vor) is one of the trigger expressions and takes the same comma + zu pattern.', 'vorhaben (ich habe vor) ist einer der Auslöser und nimmt dasselbe Muster: Komma + zu.', 'Separable Verbs with zu: an-zu-rufen'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8f88ee61-1fb6-5423-abf3-1454eb93354b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4a3a21f2-eb29-5631-8854-e518eb079ae4'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 4, 'fill_blank', 'Wir fangen an, die Küche ___. (aufräumen)', 'Fill in the separable verb with zu: We''re starting to tidy up the kitchen. (verb: aufräumen — separable)', NULL, 'aufzuräumen', '["aufzuräumen"]'::jsonb, 'aufräumen is separable: zu slots between auf- and -räumen: aufzuräumen.', 'aufräumen ist trennbar: zu kommt zwischen auf- und -räumen: aufzuräumen.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'anfangen itself is separable in the main clause; its zu-clause here holds a second separable verb.', 'anfangen ist selbst trennbar im Hauptsatz; im zu-Satz steckt hier noch ein trennbares Verb.', 'Separable Verbs with zu: an-zu-rufen'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4a3a21f2-eb29-5631-8854-e518eb079ae4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8ef377ca-6e71-50cd-8c1b-933692ff6424'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 4, 'fill_blank', 'Es ist leicht, den Weg ___. (finden)', 'Fill in the zu-infinitive: It''s easy to find the way. (verb: finden)', NULL, 'zu finden', '["zu finden"]'::jsonb, 'es ist leicht takes the same pattern: comma, then zu + infinitive at the end.', 'es ist leicht nimmt dasselbe Muster: Komma, dann zu + Infinitiv am Ende.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'finden is not separable, so zu stands directly in front of it.', 'finden ist nicht trennbar, zu steht direkt davor.', 'Verbs and Expressions Before zu + Infinitive'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8ef377ca-6e71-50cd-8c1b-933692ff6424'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4eb3e9c5-6e6e-57f4-91ef-032d0a45aa8d'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 4, 'error_correction', 'Finde den Fehler: Er kann heute nicht zu kommen.', 'Correct the sentence. Modal verbs never take zu. (He can''t come today.)', NULL, 'Er kann heute nicht kommen.', '["Er kann heute nicht kommen.","Er kann heute nicht kommen"]'::jsonb, 'können is a modal verb; modals always take a bare infinitive, never zu.', 'können ist ein Modalverb. Modalverben stehen immer mit bloßem Infinitiv, nie mit zu.', NULL, 7, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Remove zu: a modal plus infinitive needs no zu at all.', 'zu einfach weglassen: Modalverb + Infinitiv braucht kein zu.', 'No zu: Modal Verbs and gehen, bleiben, lassen, sehen, hören'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4eb3e9c5-6e6e-57f4-91ef-032d0a45aa8d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2ce189f3-dbf8-5589-980e-faa92943ee5a'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 4, 'error_correction', 'Finde den Fehler: Es ist wichtig pünktlich zu kommen.', 'Correct the sentence: a comma is missing before the zu-group. (It''s important to arrive punctually.)', NULL, 'Es ist wichtig, pünktlich zu kommen.', '["Es ist wichtig, pünktlich zu kommen.","Es ist wichtig, pünktlich zu kommen"]'::jsonb, 'After es ist wichtig the comma is obligatory.', 'Nach es ist wichtig steht immer ein Komma.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Insert the comma right after wichtig; nothing else changes.', 'Das Komma kommt direkt nach wichtig, sonst ändert sich nichts.', 'Building the zu-Infinitive and the Comma'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2ce189f3-dbf8-5589-980e-faa92943ee5a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1d5de09f-85d0-5379-bf81-5dfd133b9ee5'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence is correct? We''re going dancing tonight.', '["Wir gehen heute Abend zu tanzen.","Wir gehen heute Abend tanzen zu.","Wir gehen heute Abend tanzen.","Wir gehen zu heute Abend tanzen."]'::jsonb, 'Wir gehen heute Abend tanzen.', NULL, 'gehen takes a bare infinitive: no zu at all, even with a time expression in between.', 'gehen steht mit bloßem Infinitiv, ganz ohne zu — auch mit einer Zeitangabe dazwischen.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The other options wrongly add a zu that gehen, unlike most verbs on this page, never takes.', 'Die anderen Optionen setzen ein zu ein. Aber gehen braucht nie ein zu.', 'No zu: Modal Verbs and gehen, bleiben, lassen, sehen, hören'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1d5de09f-85d0-5379-bf81-5dfd133b9ee5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '36fbd63e-2ece-5aa4-b76d-6fc3d388541f'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence is correct? It''s nice to see my old friends.', '["Es ist schön, die alten Freunde zu sehen.","Es ist schön die alten Freunde zu sehen.","Es ist schön, die alten Freunde sehen zu.","Es ist schön, zu sehen die alten Freunde."]'::jsonb, 'Es ist schön, die alten Freunde zu sehen.', NULL, 'Comma after schön, then the object, then zu + infinitive at the very end.', 'Komma nach schön, dann das Objekt, dann zu + Infinitiv ganz am Ende.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The infinitive with zu always closes the sentence; the object comes before it.', 'Der Infinitiv mit zu steht immer am Ende; das Objekt kommt davor.', 'Es ist … zu / Ich finde es … zu'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '36fbd63e-2ece-5aa4-b76d-6fc3d388541f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '33a5ef9b-9751-5b65-929e-fcb572c7de74'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence is correct? It''s forbidden to make phone calls on the train.', '["Es ist verboten, im Zug zu telefonieren.","Es ist verboten im Zug zu telefonieren.","Es ist verboten, im Zug telefonieren zu.","Im Zug ist verboten, zu telefonieren."]'::jsonb, 'Es ist verboten, im Zug zu telefonieren.', NULL, 'verboten sein takes the standard pattern: comma, then zu + infinitive at the end.', 'verboten sein nimmt das Standardmuster: Komma, dann zu + Infinitiv am Ende.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only one option keeps the comma in place and the zu-infinitive whole at the end.', 'Nur eine Option hat das Komma richtig gesetzt und den zu-Infinitiv ungetrennt am Ende.', 'Es ist … zu / Ich finde es … zu'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '33a5ef9b-9751-5b65-929e-fcb572c7de74'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e8762ebd-a44b-5ebc-a078-2428b92ae922'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence is correct? She stopped eating sweets.', '["Sie hat aufgehört, Süßigkeiten zu essen.","Sie hat aufgehört, Süßigkeiten essen.","Sie hat aufgehört, Süßigkeiten essen zu.","Sie ist aufgehört, Süßigkeiten zu essen."]'::jsonb, 'Sie hat aufgehört, Süßigkeiten zu essen.', NULL, 'aufhören builds its Perfekt with haben, and zu stands directly before essen.', 'aufhören bildet das Perfekt mit haben, und zu steht direkt vor essen.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ist aufgehört uses the wrong auxiliary. Option two is missing zu, and option three splits zu essen apart.', 'ist aufgehört hat das falsche Hilfsverb. Option zwei hat kein zu, Option drei trennt zu essen.', 'Verbs and Expressions Before zu + Infinitive'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e8762ebd-a44b-5ebc-a078-2428b92ae922'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bd98bbf7-9a27-58ef-bcff-86cfbb0b88a1'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence is correct? It''s fun to sit outside in summer.', '["Es macht Spaß, im Sommer draußen zu sitzen.","Es macht Spaß im Sommer draußen zu sitzen.","Es macht Spaß, im Sommer draußen sitzen zu.","Es macht, Spaß im Sommer draußen zu sitzen."]'::jsonb, 'Es macht Spaß, im Sommer draußen zu sitzen.', NULL, 'Spaß machen takes the standard pattern too: comma, then zu + infinitive at the end.', 'Auch Spaß machen nimmt das Standardmuster: Komma, dann zu + Infinitiv am Ende.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The comma belongs after Spaß, not before it, and zu sitzen must stay together at the end.', 'Das Komma gehört nach Spaß, nicht davor, und zu sitzen muss am Ende zusammenbleiben.', 'Verbs and Expressions Before zu + Infinitive'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bd98bbf7-9a27-58ef-bcff-86cfbb0b88a1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c633ee48-fefd-58d8-a8af-94dd88568785'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / Lust haben / heute / schwimmen gehen]', 'Write the sentence: I feel like going swimming today. (Lust haben, ich; comma before the zu-group)', NULL, 'Ich habe Lust, heute schwimmen zu gehen.', '["Ich habe Lust, heute schwimmen zu gehen.","Ich habe Lust, heute schwimmen zu gehen","Heute habe ich Lust, schwimmen zu gehen.","Heute habe ich Lust, schwimmen zu gehen","Ich habe heute Lust, schwimmen zu gehen.","Ich habe heute Lust, schwimmen zu gehen"]'::jsonb, 'Lust haben, comma, then zu gehen at the end; schwimmen (bare) stands right before it.', 'Lust haben, Komma, dann zu gehen am Ende; schwimmen steht direkt davor.', NULL, 1, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'heute may also open the sentence; habe ich then follows in positions 2-3.', 'heute kann auch am Anfang stehen; dann folgt habe ich.', 'Building the zu-Infinitive and the Comma'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c633ee48-fefd-58d8-a8af-94dd88568785'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '17b723c7-cac1-52a9-bc90-6165ee820c72'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / keine Zeit haben / heute Nachmittag / Fußball spielen]', 'Write the sentence: We have no time to play football this afternoon. (keine Zeit haben, wir)', NULL, 'Wir haben keine Zeit, heute Nachmittag Fußball zu spielen.', '["Wir haben keine Zeit, heute Nachmittag Fußball zu spielen.","Wir haben keine Zeit, heute Nachmittag Fußball zu spielen","Heute Nachmittag haben wir keine Zeit, Fußball zu spielen.","Heute Nachmittag haben wir keine Zeit, Fußball zu spielen","Wir haben heute Nachmittag keine Zeit, Fußball zu spielen.","Wir haben heute Nachmittag keine Zeit, Fußball zu spielen"]'::jsonb, 'keine Zeit haben, comma, then the object and zu spielen at the end.', 'keine Zeit haben, Komma, dann das Objekt und zu spielen am Ende.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'heute Nachmittag may open the sentence instead; keine Zeit haben still keeps its comma.', 'heute Nachmittag kann auch vorn stehen; keine Zeit haben behält trotzdem sein Komma.', 'Verbs and Expressions Before zu + Infinitive'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '17b723c7-cac1-52a9-bc90-6165ee820c72'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '76b4d2e6-0007-5e3d-8c60-3d3485833187'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 5, 'sentence_building', 'Schreib den Satz im Perfekt: [ich / vergessen / die Tür / abschließen]', 'Write the sentence in the Perfekt: I forgot to lock the door. (vergessen, Perfekt, ich; abschließen is separable — zu goes inside)', NULL, 'Ich habe vergessen, die Tür abzuschließen.', '["Ich habe vergessen, die Tür abzuschließen.","Ich habe vergessen, die Tür abzuschließen","Ich habe vergessen die Tür abzuschließen.","Ich habe vergessen die Tür abzuschließen"]'::jsonb, 'habe vergessen (Perfekt) plus comma plus abzuschließen (abschließen with zu inside) at the end.', 'habe vergessen (Perfekt) plus Komma plus abzuschließen (abschließen mit zu innen) am Ende.', NULL, 3, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'abschließen is separable, so zu is inserted between ab- and -schließen: abzuschließen.', 'abschließen ist trennbar, deshalb steht zu zwischen ab- und -schließen: abzuschließen.', 'Separable Verbs with zu: an-zu-rufen'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '76b4d2e6-0007-5e3d-8c60-3d3485833187'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a00a8354-dec0-5687-bb3d-d849a81b1d25'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / versuchen / jeden Abend / früh einschlafen]', 'Write the sentence: I try to fall asleep early every evening. (versuchen, ich; einschlafen is separable)', NULL, 'Ich versuche, jeden Abend früh einzuschlafen.', '["Ich versuche, jeden Abend früh einzuschlafen.","Ich versuche, jeden Abend früh einzuschlafen","Jeden Abend versuche ich, früh einzuschlafen.","Jeden Abend versuche ich, früh einzuschlafen","Ich versuche jeden Abend früh einzuschlafen.","Ich versuche jeden Abend früh einzuschlafen"]'::jsonb, 'versuchen, comma, then einzuschlafen (einschlafen with zu inside) at the end.', 'versuchen, Komma, dann einzuschlafen (einschlafen mit zu innen) am Ende.', NULL, 4, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'jeden Abend may also open the sentence; versuche then keeps position 2.', 'jeden Abend kann auch am Anfang stehen; versuche bleibt dann auf Position 2.', 'Separable Verbs with zu: an-zu-rufen'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a00a8354-dec0-5687-bb3d-d849a81b1d25'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0bfab594-5f89-5d7c-a9bc-1cf690a4e8e7'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 5, 'sentence_building', 'Schreib den Satz: [mein Kollege / anfangen / im September / Spanisch lernen]', 'Write the sentence: My colleague is starting to learn Spanish in September. (anfangen, er/sie)', NULL, 'Mein Kollege fängt im September an, Spanisch zu lernen.', '["Mein Kollege fängt im September an, Spanisch zu lernen.","Mein Kollege fängt im September an, Spanisch zu lernen","Mein Kollege fängt im September an Spanisch zu lernen.","Mein Kollege fängt im September an Spanisch zu lernen","Im September fängt mein Kollege an, Spanisch zu lernen.","Im September fängt mein Kollege an, Spanisch zu lernen","Mein Kollege fängt an, im September Spanisch zu lernen.","Mein Kollege fängt an, im September Spanisch zu lernen","Im September fängt mein Kollege an Spanisch zu lernen.","Im September fängt mein Kollege an Spanisch zu lernen","Mein Kollege fängt an im September Spanisch zu lernen.","Mein Kollege fängt an im September Spanisch zu lernen"]'::jsonb, 'im September can stand in the main clause or inside the zu-clause. The comma before the zu-group is optional after anfangen.', 'im September kann im Hauptsatz oder im zu-Satz stehen. Das Komma vor der zu-Gruppe ist nach anfangen optional.', NULL, 5, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'fängt takes position 2, an closes the main clause, and Spanisch zu lernen follows the comma.', 'fängt steht auf Position 2, an schließt den Hauptsatz, danach folgt Spanisch zu lernen.', 'Building the zu-Infinitive and the Comma'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0bfab594-5f89-5d7c-a9bc-1cf690a4e8e7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'be2aa3ab-7736-5887-b98e-d01ac8a9fe15'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / aufhören / so viel / Kaffee trinken]', 'Write the sentence: I''m going to stop drinking so much coffee. (aufhören, ich)', NULL, 'Ich höre auf, so viel Kaffee zu trinken.', '["Ich höre auf, so viel Kaffee zu trinken.","Ich höre auf, so viel Kaffee zu trinken","Ich höre auf so viel Kaffee zu trinken.","Ich höre auf so viel Kaffee zu trinken"]'::jsonb, 'höre auf (aufhören) closes with auf, then comma, then the object and zu trinken.', 'höre auf (aufhören) endet mit auf, dann Komma, dann das Objekt und zu trinken.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'so viel Kaffee stays together right before zu trinken at the very end.', 'so viel Kaffee bleibt zusammen direkt vor zu trinken ganz am Ende.', 'Verbs and Expressions Before zu + Infinitive'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'be2aa3ab-7736-5887-b98e-d01ac8a9fe15'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c0f56d7a-bbce-5feb-9fca-2c8262066725'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / vorhaben / im Winter / nach München umziehen]', 'Write the sentence: We''re planning to move to Munich in the winter. (vorhaben, wir; umziehen is separable — zu goes inside)', NULL, 'Wir haben vor, im Winter nach München umzuziehen.', '["Wir haben vor, im Winter nach München umzuziehen.","Wir haben vor, im Winter nach München umzuziehen","Wir haben vor im Winter nach München umzuziehen.","Wir haben vor im Winter nach München umzuziehen","Im Winter haben wir vor, nach München umzuziehen.","Im Winter haben wir vor, nach München umzuziehen","Wir haben im Winter vor, nach München umzuziehen.","Wir haben im Winter vor, nach München umzuziehen"]'::jsonb, 'haben vor (vorhaben) closes with vor, then umzuziehen (umziehen with zu inside) at the end.', 'haben vor (vorhaben) endet mit vor, dann umzuziehen (umziehen mit zu innen) am Ende.', NULL, 7, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'umziehen is separable, so zu goes inside it: umzuziehen; im Winter may sit in the main clause or open the sentence.', 'umziehen ist trennbar, zu kommt hinein: umzuziehen; im Winter kann im Hauptsatz oder am Anfang stehen.', 'Separable Verbs with zu: an-zu-rufen'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c0f56d7a-bbce-5feb-9fca-2c8262066725'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '60a201f4-694c-56eb-8c99-93130a8847f5'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 5, 'sentence_building', 'Schreib den Satz: [sie / keine Angst haben / mit dem Bus / fahren]', 'Write the sentence: She''s not afraid to ride the bus. (keine Angst haben, sie)', NULL, 'Sie hat keine Angst, mit dem Bus zu fahren.', '["Sie hat keine Angst, mit dem Bus zu fahren.","Sie hat keine Angst, mit dem Bus zu fahren"]'::jsonb, 'keine Angst haben, comma, then mit dem Bus zu fahren at the end.', 'keine Angst haben, Komma, dann mit dem Bus zu fahren am Ende.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'fahren is not separable, so zu simply stands in front of it.', 'fahren ist nicht trennbar, zu steht einfach davor.', 'Verbs and Expressions Before zu + Infinitive'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '60a201f4-694c-56eb-8c99-93130a8847f5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '12da8e6f-a9ab-57e8-953b-cccc6a5c5a7d'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / finden / es / leicht / hier / Freunde finden]', 'Write the sentence: I find it easy to make friends here. (ich finde es + adjective, leicht)', NULL, 'Ich finde es leicht, hier Freunde zu finden.', '["Ich finde es leicht, hier Freunde zu finden.","Ich finde es leicht, hier Freunde zu finden","Hier finde ich es leicht, Freunde zu finden.","Hier finde ich es leicht, Freunde zu finden"]'::jsonb, 'ich finde es + adjective takes a comma and zu + infinitive. It works just like es ist + adjective.', 'ich finde es + Adjektiv nimmt Komma und zu + Infinitiv. Das ist genau wie bei es ist + Adjektiv.', NULL, 9, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'hier Freunde stays together right before zu finden at the very end.', 'hier Freunde bleibt zusammen direkt vor zu finden ganz am Ende.', 'Es ist … zu / Ich finde es … zu'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '12da8e6f-a9ab-57e8-953b-cccc6a5c5a7d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1726dba1-704c-5390-9923-c8b4b1e27d97'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 5, 'sentence_building', 'Schreib den Satz: [es / erlaubt sein / in der Bibliothek / leise sprechen]', 'Write the sentence: It''s allowed to talk quietly in the library. (erlaubt sein, es ist)', NULL, 'Es ist erlaubt, in der Bibliothek leise zu sprechen.', '["Es ist erlaubt, in der Bibliothek leise zu sprechen.","Es ist erlaubt, in der Bibliothek leise zu sprechen","In der Bibliothek ist es erlaubt, leise zu sprechen.","In der Bibliothek ist es erlaubt, leise zu sprechen"]'::jsonb, 'erlaubt sein takes the standard pattern: comma, then zu + infinitive at the end.', 'erlaubt sein nimmt das Standardmuster: Komma, dann zu + Infinitiv am Ende.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'in der Bibliothek leise stays together right before zu sprechen at the end.', 'in der Bibliothek leise bleibt zusammen direkt vor zu sprechen am Ende.', 'Es ist … zu / Ich finde es … zu'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1726dba1-704c-5390-9923-c8b4b1e27d97'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7333c55d-fd8b-50fc-90ea-ca24ab01a335'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 5, 'sentence_building', 'Schreib den Satz: [es / schwer sein / am Montag / pünktlich aufstehen]', 'Write the sentence: It''s hard to get up on time on Mondays. (es ist schwer)', NULL, 'Es ist schwer, am Montag pünktlich aufzustehen.', '["Es ist schwer, am Montag pünktlich aufzustehen.","Es ist schwer, am Montag pünktlich aufzustehen","Am Montag ist es schwer, pünktlich aufzustehen.","Am Montag ist es schwer, pünktlich aufzustehen","Es ist am Montag schwer, pünktlich aufzustehen.","Es ist am Montag schwer, pünktlich aufzustehen"]'::jsonb, 'es ist schwer, comma, then aufzustehen (aufstehen with zu inside) at the end.', 'es ist schwer, Komma, dann aufzustehen (aufstehen mit zu innen) am Ende.', NULL, 11, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'am Montag may also open the sentence; then the verb inverts to ist es.', 'am Montag kann auch am Anfang stehen; dann folgt ist es.', 'Es ist … zu / Ich finde es … zu'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7333c55d-fd8b-50fc-90ea-ca24ab01a335'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f0bcd17d-566c-59e2-8569-812432198107'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 5, 'error_correction', 'Finde den Fehler: Ich vergesse oft, das Fenster auf zu machen.', 'Correct the sentence. zu belongs inside the separable verb, written as one word. (I often forget to open the window.)', NULL, 'Ich vergesse oft, das Fenster aufzumachen.', '["Ich vergesse oft, das Fenster aufzumachen.","Ich vergesse oft, das Fenster aufzumachen","Ich vergesse oft das Fenster aufzumachen.","Ich vergesse oft das Fenster aufzumachen"]'::jsonb, 'aufmachen is one separable verb; zu goes inside it: aufzumachen, not auf zu machen.', 'aufmachen ist ein trennbares Verb; zu kommt hinein: aufzumachen, nicht auf zu machen.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Join auf, zu and machen into one word with zu in the middle: aufzumachen.', 'auf, zu und machen werden ein Wort mit zu in der Mitte: aufzumachen.', 'Separable Verbs with zu: an-zu-rufen'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f0bcd17d-566c-59e2-8569-812432198107'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '31b33a09-6c89-5f3b-b4ef-7491d4ee1697'::uuid, '6d0105ab-a70c-5e1b-b0ee-a923896f0c94'::uuid, 5, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence has correct word order for: We forgot to call the doctor.', '["Wir haben vergessen, den Arzt anzurufen.","Wir haben vergessen, anzurufen den Arzt.","Wir haben den Arzt vergessen, anzurufen.","Wir haben vergessen den Arzt, anzurufen."]'::jsonb, 'Wir haben vergessen, den Arzt anzurufen.', NULL, 'The comma comes right after vergessen. The object den Arzt stands before anzurufen. anzurufen closes the sentence.', 'Das Komma steht direkt nach vergessen. Das Objekt den Arzt steht vor anzurufen. anzurufen beendet den Satz.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only one order sets the comma correctly. Only it keeps the whole zu-infinitive block unbroken at the end.', 'Nur eine Reihenfolge setzt das Komma richtig. Nur dort bleibt der ganze zu-Block ungetrennt am Ende.', 'Building the zu-Infinitive and the Comma'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '31b33a09-6c89-5f3b-b4ef-7491d4ee1697'::uuid);


COMMIT;

